026 21:17:33', '12-04-2026 21:17:33', '2026-04-12', NULL, NULL, '2026-04-12T00:00:00-03:00', NULL, NULL, 5, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13406034_bum_v39597a9d.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118228560.html', '2026-04-13T07:05:55.097853');
