INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227310, NULL, 'Administrativo Junior', 'Confidencial', '🚀 Estamos buscando Auxiliar Administrativo.Importante empresa se encuentra en la búsqueda de Auxiiar Administrativo para el area contable. Nuestra logistica se encuentra ubicada dentro del Parque Industrial de Ezeiza.Nos orientamos a perfiles organizados, proactivos y con buenas habilidades de comunicación, que cuenten con experiencia en tareas administrativas generales.📌 Principales responsabilidades Ingreso de comprobantes en sistema de gestión. Archivo y organización de documentación física y digital. Seguimiento de cuentas corrientes. Asistencia en tareas de cobranzas y pagos. Atención telefónica y soporte administrativo general. Coordinación de trámites y gestiones. Apoyo en cierres mensuales y elaboración de reportes básicos.✅ Requisitos Experiencia comprobable mínima de 1 año en posiciones similares. Formación académica: estudios terciarios y/o universitarios en Administración de Empresas, Contabilidad o afines. Manejo de sistemas de gestión (Bejerman o similares – deseable). Residir en Zona Sur. Manejo de Excel (nivel básico/intermedio). Contar con movilidad propia.📌 Modalidad: Presencial - Parque industrial de Ezeiza. Jornada Full Time, de Lunes a Viernes de 08:30 a 18:00 hs.⏳ 📩 Si querés formar parte de una empresa con trayectoria, estabilidad y proyección, postulate por este medio.', 1, 'Ezeiza, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 16:13:42', '10-04-2026 16:13:55', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, NULL, NULL, NULL, NULL, 40, 'Destacados', 'bumeran', 'destacado', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227310.html', '2026-04-13T07:05:55.099985');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227505, 1282780, 'Administrativa de Venta', 'Adecco - Permanent Talent', 'BUSCAMOS TALENTOS, ¡EN ADECCO TE ESTAMOS BUSCANDO!Si te interesa desarrollarte como Administrativa de venta en Haedo en el equipo de nuestro cliente IMPORTANTE EMPRESA ¡desafíate a vos mismo y crea tu futuro!¿QUÉ DESAFÍOS TE ESPERAN? Gestión administrativa de las operaciones de ventas. Control y seguimiento de cuentas corrientes de clientes. Gestión y seguimiento de órdenes de compra. Seguimiento de pagos y cobranzas. Emisión y control de documentación comercial: facturas, remitos y notas de crédito. Atención administrativa a clientes y red de concesionarios. Coordinación con las áreas contable y logística. Resolución de consultas administrativas vinculadas al área comercial.¿QUÉ VALORAMOS DE TU PERFIL? Formación en Administración de Empresas, Comercialización o carreras afines (deseable). Experiencia previa en tareas administrativas de ventas o back office comercial. Buen manejo de Excel y herramientas administrativas. Experiencia en manejo de cuentas corrientes y seguimiento de cobranzas. Se valorará experiencia con clientes corporativos o redes comerciales.¿QUE TE OFRECEMOS? Lugar de trabajo: HAEDO Jornada laboral: lunes a viernes fulltime Modalidad laboral: presencialSomos Adecco Argentina una compañía con más de 30 años de experiencia que conecta empresas con talentos, brindando soluciones integrales de Recursos Humanos y buscamos talentos, ¡COMO VOS!Nuestro compromiso, es la #diversidad e #igualdad de oportunidades somos una empresa inclusiva. Cuando sos parte de nuestros procesos, solo cuentan tus méritos, logros y capacidades, lo hacemos pensando en vos como persona.Participar de nuestros procesos de selección no tiene ningún costo para vos candidato/a, trabajar con vos es parte de nuestro compromiso y tarea con la comunidad. Postulate y participa en una oferta de empleo nuestra.El empleador sólo podrá solicitarle la información estrictamente necesaria para el desempeño en el trabajo que se ofrece.Ciudad de Buenos Aires: ley de búsqueda laboral equitativa - Ley 6471', 0, 'Haedo, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 17:39:24', '10-04-2026 17:39:24', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 6, 23, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/0/1/2/8/2/7/8/0/logoMainPic_1282780_bum_vf37880d6.jpg', 0, 0, 3.73, 70, 'Simples', 'bumeran', 'simple', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227505.html', '2026-04-13T07:05:55.100125');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227048, 444640, 'Administrativo/a de ventas', 'Grupo Gestión', 'Importante empresa del rubro textil, dedicada a la fabricación de productos de algodón, protección femenina, pañales y soluciones para la incontinencia, se encuentra en la búsqueda de una Administrativa/o de ventasNos orientamos a un perfil dinámico, resolutivo y organizado, con experiencia en administración comercial y seguimiento integral de pedidos.Principales responsabilidades: Carga y seguimiento de pedidos Coordinación con vendedores y distribuidores Control de stock y disponibilidad Seguimiento de entregas y logística Atención y soporte a clientesRequisitos: Experiencia en administración de ventas (preferentemente en consumo masivo). Manejo de Excel intermedio/avanzado. Experiencia con Tango Gestión (valorado). Perfil resolutivo, con buen manejo interpersonal. Residencia en San Justo o zonas cercanas (excluyente).Jornada: Lunes a viernes de 8 a 17 hs, posición 100% presencial.Ingreso por consultora (Convenio SETIA), con posibilidad de efectivización.Si te interesa formar parte de una compañía industrial con trayectoria en el mercado, ¡esperamos tu postulación!', 0, 'San Justo, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 14:21:15', '10-04-2026 14:21:15', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_444640_bum_vce78c1c9.jpg', 1, 0, 4.02, 70, 'Simples', 'bumeran', 'simple', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227048.html', '2026-04-13T07:05:55.100229');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226670, NULL, 'AUXILIAR ADMINISTRATIVO/A', 'Confidencial', '📌 AUXILIAR ADMINISTRATIVO/A📍 La Reja (Moreno) - 🕒 Lunes a Viernes de 8:00 a 17:00 hsObjetivo del puestoBrindar soporte administrativo al área de Administración y Finanzas, asegurando el orden documental, la correcta registración operativa, el seguimiento de vencimientos con relación a rodados y medios de elevación, contribuyendo al cumplimiento y la organización del sector.Principales responsabilidades* Gestionar, controlar y archivar documentación administrativa y contable.* Brindar soporte operativo en el procesamiento administrativo de facturas y comprobantes, una vez validados y aprobados por la jefatura.* Administrar legajos y coordinar el envío periódico de documentación a estudio contable y otros organismos.* Gestionar pólizas, documentación de vehículos, maquinarias y personal, así como el seguimiento administrativo de siniestros.* Controlar vencimientos legales, técnicos y operativos vinculados a seguros, flota y documentación obligatoria.* Brindar soporte administrativo general al área en temas de insumos, servicios internos y recepción de proveedores y clientes.Requisitos del perfil* Experiencia previa en tareas administrativas generales.*Residir en la zona.* Manejo de documentación, archivo y control de información.* Deseable experiencia en carga de comprobantes, legajos, seguros o control de vencimientos.* Buen manejo de herramientas informáticas y paquete Office, especialmente Excel.Competencias buscadas* Orden y prolijidad en el trabajo.* Atención al detalle y seguimiento.* Responsabilidad y constancia.* Capacidad para trabajar con documentación y tareas rutinarias.* Buenas habilidades de organización y apoyo al equipo.', 1, 'Moreno, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 11:43:38', '10-04-2026 11:43:38', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226670.html', '2026-04-13T07:05:55.100363');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118217316, 13008239, 'ASISTENTE ADMINISTRATIVA', 'PROVETEL ARGENTINA S.A.', 'BÚSQUEDA LABORAL: Asistente Administrativa / Auxiliar de OficinaEstamos sumando a nuestro equipo una Asistente Administrativa para brindar soporte operativo en nuestra oficina ubicada en Barracas. Buscamos una persona responsable, detallista y con buena predisposición para tareas integrales de oficina.¿Cuáles serán tus tareas?En esta posición, asistirás en el día a día administrativo realizando: Soporte General: Organización de archivos físicos/digitales, gestión de correo electrónico y tareas generales de oficina. Data Entry: Ingreso de facturas, impuestos, servicios y movimientos bancarios en el sistema de gestión. Asistencia en Caja: Colaboración en la recepción de pagos (efectivo, cheques, tarjetas) y emisión de recibos. Gestiones Externas: Realización de trámites bancarios o administrativos de forma muy esporádica y puntual.Requisitos Excluyentes (Sin excepción): Edad: Entre 35 y 45 años. Disponibilidad: Buscamos un perfil con foco exclusivo en el trabajo, por lo que es requisito no encontrarse cursando estudios actualmente. Experiencia: Experiencia previa comprobable en tareas de oficina o asistencia administrativa. Educación: Secundario completo.Perfil buscado: Persona metódica, puntual y con marcada atención al detalle. Predisposición para realizar tareas variadas según la necesidad de la oficina. Buen manejo de herramientas informáticas (Excel, Mail, sistemas de gestión). Se valora residencia en zonas aledañas (no excluyente)Ofrecemos: Estabilidad laboral y contratación inmediata. Horario fijo de lunes a viernes. Muy buen clima laboral.¡Postulate! Envianos tu CV actualizado indicando remuneración pretendida.', 0, 'Buenos Aires, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 15:42:14', '12-04-2026 18:49:44', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/1/3/0/0/8/2/3/9/logoMainPic_13008239_bum_ve10aa922.jpg', 0, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118217316.html', '2026-04-13T07:05:55.100492');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225656, 13473914, 'Administrativo Inmobiliario', 'duek propiedades', 'Nuestro pequeño grupo PYMES con 4 2 años de trayectoria en Balvanera busca integrar administrativa con comprobable experiencia inmobiliaria, carácter ejecutivo y buenas relaciones humanas, manejo ágil de computadora. Remuneración a convenir, que resida en capital federal, horarios de lunes a viernes.Principales responsabilidades: Atención telefónica, vía WhatsApp y presencial de clientes. Carga y actualización de propiedades en portales inmobiliarios. Gestión de agenda, coordinación de visitas y tasaciones. Archivo de documentación y tareas administrativas generales de oficina. Seguimiento de consultas y potenciales clientes.Requisitos Experiencia previa en el sector inmobiliario. Buenas relaciones interpersonales. Manejo ágil de herramientas informáticas. Disponibilidad para trabajar en horarios regulares de lunes a viernes.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 10:21:34', '10-04-2026 12:14:32', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 26, 2572, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225656.html', '2026-04-13T07:05:55.100595');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224076, 2048100, 'Administrativo/a para JEEP', 'Grupo Taraborelli', 'Grupo Taraborelli está conformado por 10 empresas y más de 700 colaboradores. Nos desempeñamos en la industria automotriz, comercializando autos, pickups, camiones, vans y maquinaria agrícola.Además, contamos con una rentadora de autos, orientada tanto al turismo como a servicios corporativos.Este año celebramos con orgullo nuestro 40º aniversario, respaldados por una sólida trayectoria que nos ha posicionado como referentes estables en la industria automotrizSomos un grupo con proyección nacional, operando en distintos puntos del país.Representamos oficialmente marcas como Ford, Fiat, Mercedes-Benz, Jeep, RAM, Peugeot y New Holland (Agro). Estamos en la búsqueda de un/a Administrativo/a de Patentamiento para Jeep. Tus principales responsabilidades serán: Coordinar y citar a clientes para gestionar firmas y trámites. Llevar registro del calendario de entrega. Administrar pagos y completar la documentación necesaria para el patentamiento de vehículos (formularios). Gestionar la recepción de documentación de autos usados, asegurando un proceso eficiente y ordenado. Valoramos aquellas personas con excelente relaciones interpersonales, tanto con clientes como con compañeros de trabajo y aquellas personas con atención a los detallesSi te apasionan los desafíos administrativos y querés formar parte de una empresa líder en el mercado automotriz, ¡te estamos buscando!Confirmame o modificá lo que sea necesario Requisitos: Experiencia en posiciones similares de al menos 1 año (rubro automotriz). Experiencia en la toma de firmas a clientes y gestión de trámites administrativos de al menos 1 año Conocimiento y experiencia en el manejo de documentación relacionada con autos usados. de al menos 1 año Manejo de herramientas tecnológicas aplicadas a la gestión administrativa.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 15:22:26', '10-04-2026 15:22:26', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2048100_bum_vf2ce8646.jpg', 1, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224076.html', '2026-04-13T07:05:55.100730');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224035, 2048100, 'Administrativo/a para FIAT', 'Grupo Taraborelli', 'Grupo Taraborelli está conformado por 10 empresas y más de 700 colaboradores. Nos desempeñamos en la industria automotriz, comercializando autos, pickups, camiones, vans y maquinaria agrícola.Además, contamos con una rentadora de autos, orientada tanto al turismo como a servicios corporativos.Este año celebramos con orgullo nuestro 40º aniversario, respaldados por una sólida trayectoria que nos ha posicionado como referentes estables en la industria automotrizSomos un grupo con proyección nacional, operando en distintos puntos del país.Representamos oficialmente marcas como Ford, Fiat, Mercedes-Benz, Jeep, RAM, Peugeot y New Holland (Agro). Nos encontramos en la búsqueda de un/a Administrativo/a para el área de Patentamiento, con experiencia comprobable en gestión documental automotriz. La persona seleccionada será responsable de llevar adelante tareas clave vinculadas a la administración y seguimiento de documentación de unidades 0km y usadas.Principales responsabilidades: Gestión integral y seguimiento de prendas (alta, baja, levantamientos, etc.). Administración y control de documentación de vehículos usados. Interacción con registros seccionales y entes gubernamentales. Carga y gestión de datos en sistema FBS. Seguimiento de procesos administrativos internos hasta la finalización del patentamiento. Reportes y seguimiento de documentación mediante herramientas como Microsoft Excel. Coordinación con áreas internas (ventas, stock, logística) para asegurar cumplimiento de plazos.Valoramos: Proactividad para detectar mejoras en los procesos. Capacidad para trabajar en equipo y buenas relaciones interpersonales. Experiencia en atención a clientes internos/externos Requisitos:', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 15:07:19', '10-04-2026 15:07:19', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2048100_bum_vf2ce8646.jpg', 1, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224035.html', '2026-04-13T07:05:55.100865');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225363, NULL, 'ADMINISTRATIVA/O DE COMPRAS', 'Confidencial', 'Buscamos ADMINISTRATIVA/O DE COMPRAS Sera su propósito el de analizar y optimizar los procesos de compras y gestión de precios de la empresa, asegurando la adquisición de productos al mejor precio posible. Tareas: Analizar y evaluar las necesidades de compra de la empresa. Investigar y recomendar proveedores y fuentes de suministro . Negociar precios y condiciones de compra con proveedores. Desarrollar y mantener relaciones con proveedores. Analizar y comparar precios de mercado para asegurar la competitividad. Identificar oportunidades de ahorro y reducción de costos . Responsabilidad del abastecimiento general.¿Qué requisitos buscamos en los candidatos? Experiencia previa en posiciones similares. Manejo de office. Capacidad analítica, flexibilidad, y honestidad. Excelente manejo de la comunicación, relacionamiento interpersonal y trabajo en equipo.Los postulantes deberan contar con disponibilidad para trabajar de LUNES a VIERNES de 8.30 a 17.30 hs PRESENCIAL en MUNRO (Gba Norte).Postulate cargando tu CV con remuneración pretendida!', 1, 'Munro, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 13:49:01', '12-04-2026 19:47:29', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, NULL, NULL, NULL, NULL, 40, 'Destacados', 'bumeran', 'destacado', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225363.html', '2026-04-13T07:05:55.100981');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224710, 13461943, 'Administrativo/a de Ventas', 'Consultora Star', '🔎 Búsqueda Laboral | Administrativo/a de Ventas | Tres ArroyosImportante agroveterinaria, distribuidora mayorista de productos agro-veterinarios, se encuentra en la búsqueda de un/a Administrativo/a de Ventas para incorporarse a su equipo de trabajo.🕒 Jornada laboral: Lunes a viernes de 8:00 a 12:30hs y de 15:00 a 19:00hs🔶 Principales responsabilidades: Administración de cuentas corrientes de clientes y proveedores Facturación Pago a proveedores Gestión de cobranzas🔷 Requisitos: Residir en Tres Arroyos, provincia de Buenos Aires (excluyente) Experiencia en posiciones administrativas dentro de comercios o áreas de ventas (deseable) Formación en administración o afines (deseable) Conocimiento del sistema Tango (deseable) Perfil responsable, proactivo, organizado y con capacidad de trabajo en equipo✨ Se ofrece: Incorporación inmediata Posición efectiva Capacitaciones a cargo de la empresa Posibilidades de crecimiento y desarrollo profesional¡Seguinos en nuestras redes! 👉 LinkedIn: consultorastar 👉 Instagram: consultorastar.tresarroyos', 0, 'Tres Arroyos, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 07:27:04', '09-04-2026 07:27:56', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13461943_bum_v8f0cf941.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224710.html', '2026-04-13T07:05:55.101111');
