INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2178999, 622809, 'Ejecutivo de cuentas alimentos congelados - canal industria', 'Sélica', 'Para empresa de alimentos congelados, seleccionaremos Ejecutivo de cuentas para canal industria, con el objetivo de fidelizar clientes industriales, en búsqueda permanente de nuevas cuentas en todo el país.¿Cuáles son las funciones de la posición?- Gestión comercial de cuentas activas, atención permanente, negociación de condiciones comerciales, detección de necesidades y resolución de conflictos- Desarrollo de negocios, ampliación de cartera- Realizar proyecciones de ventas por cliente- Gestionar estrategia comercial, alineada con supply chain para disponibilidad de producto- Soporte post venta, seguimiento de reclamos, entregas- Análisis de mercado y competencia, nuevas demandas, presentación de propuestas en cuanto ajustes de precios, condiciones, en base a entorno comercial- Gestión de reportes de gestión, mantener actualizada información comercial, elaboración de propuestas, contratos y documentación técnica/comercial¿Cuáles son los requisitos de la posición?- Experiencia en rubro de alimentos congelados en atención de canal industrial (ideal) con cartera de clientes- Movilidad propia- Conocimientos de Excel, powerpoint- Competencias orientadas al trabajo en equipo, proactividad, iniciativa, con fuerte orientación a resultados en contexto dinámico- Disponibilidad horaria de lunes a viernes de 9 a 17 hs.¿Qué ofrecemos?- Relación de dependencia por tiempo indeterminado- Salario fijo y variable acorde a resultados- Ajuste por inflación trimestral- Gastos de auto y movilidad a cargo de la empresa', 0, 'Villa Adelina, Buenos Aires', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 10:43:01', '10-04-2026 13:39:59', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 6, 23, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_622809_bum_v6b3362f3.jpg', 0, 0, NULL, 1020, 'Aviso Select', 'zonajobs', 'zonajobs', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2178999.html', '2026-04-13T07:05:55.103347');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2178909, NULL, 'Analista senior de compras con experiencia en distribuidoras de alimento', 'Confidencial', '¡Unite a nuestro equipo como Analista Senior de Compras!¿Tenés solida experiencia en negociaciones estratégicas y gestión de proveedores?Principales tareas: Gestionar el ciclo completo de compras Desarrollar y mantener relaciones sólidas con proveedores clave Optimizar el abastecimiento y las transferencias Identificar oportunidades de ahorro y mejoraRequisitos: Experiencia en la posición mayor a 3 años en Distribuidoras de consumo masivo Herramientas MS office, nivel avanzado (Excel, PowerPoint, Outlook) Liderazgo Habilidades de negociación Residir en CABA o alrededoresSi estás buscando sumarte a una empresa en crecimiento y cumplís con estos requisitos esta oportunidad es para vos¿Que ofrecemos? Sumarte a una empresa en crecimiento en un puesto con proyección Prepaga de primer nivel para vos y tu grupo familiar Posición fuera de convenio Día Off de cumpleaños', 1, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '06-04-2026', '06-04-2026 11:09:05', '10-04-2026 09:44:16', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 3, 56, 1, NULL, NULL, NULL, NULL, 70, 'Avisos Classic', 'zonajobs', 'zonajobs', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2178909.html', '2026-04-13T07:05:55.103457');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226723, 13488114, 'JEFE DE DEPOSITO/ALMACEN', 'kando motos', 'Concesionario oficial líder en la Patagonia de marcas reconocidas como Honda, Yamaha, Hero, Voge, Gilera, Mondial y Motomel. Ofrecemos servicio técnico oficial especializado, junto con una amplia disponibilidad de repuestos y accesorios originales, garantizando calidad, respaldo y confianza en cada experiencia. Nos encontramos en la búsqueda de un Jefe de Almacén para liderar la operación de nuestro depósito de repuestos, asegurando una gestión eficiente del stock, la logística y la organización integral del sector.La posición tendrá como objetivo principal garantizar el control de inventarios, la correcta distribución de mercadería entre sucursales y la optimización del espacio físico, alineando la operación con los estándares de calidad y eficiencia de la compañía.Buscamos un perfil con: Alta capacidad de organización y planificación. Fuerte orientación al análisis de datos e indicadores. Buen manejo de equipos de trabajo. Capacidad de coordinación con múltiples áreas. Enfoque en mejora continua y eficiencia operativa. Requisitos: ​​​​​​Responsabilidades principales Gestionar el orden, la organización y la limpieza del almacén bajo metodologías de mejora continua. Administrar y controlar inventarios (cíclicos y generales), asegurando la trazabilidad y consistencia entre stock físico y sistema. Clasificar productos según rotación (alta, media y baja) para optimizar su ubicación y disponibilidad. Detectar y reportar diferencias de stock, mermas y productos obsoletos. Coordinar la recepción, almacenamiento y despacho de mercadería. Gestionar la logística de distribución a sucursales. Analizar puntos de pedido y planificar compras en función de rotación, ventas y objetivos comerciales. Optimizar el uso del espacio físico del almacén. Liderar y coordinar el equipo de trabajo del área de repuestos. Experiencia mínima de 3 años en gestión de depósitos, inventarios o logística (deseable mayor experiencia en posiciones similares). Secundario completo (valoramos formación en logística, compras o gestión de almacenes). Manejo de herramientas informáticas (Excel, sistemas de gestión/ERP). Conocimientos en logística, control de stock y distribución. Licencia de conducir vigente. Inglés básico (lectura técnica deseable).', 0, 'Neuquén, Neuquén', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 12:06:15', '10-04-2026 12:06:15', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 6, 2629, 1, NULL, NULL, NULL, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226723.html', '2026-04-13T07:05:55.103605');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179044, 515278, 'Operario de Almacén', 'EFEPE SA', 'Resumen del PuestoBuscamos un Operario de Depósitopara unirse a nuestro equipo. El candidato ideal tendrá un fuerte conocimiento de los principios de logística y será capaz de trabajar tanto de forma independiente como así también formando parte de un equipo. Tipo de Vacante: Full-Time Días y Horarios: Lunes a Viernes de 08:00 a 17:00 Lugar de Trabajo: San Justo, La Matanza (Zona Oeste del GBA) Comedor en plantaResponsabilidades Recibir, controlar y guardar pedidos de proveedores. Preparar y controlar pedidos de clientes. Mantener el depósito limpio y organizado. Realizar inventarios. Operar maquinaria de almacén.Requisitos Educación secundaria completa. 1+ años de experiencia en logística. Fuerte conocimiento de los principios de logística. Excelentes habilidades analíticas y de resolución de problemas. Capacidad para trabajar de forma independiente y como parte de un equipo. Excelentes habilidades de comunicación escrita y verbal. Deseable experiencia en manejo de apilable eléctrico/zorra y/o autoelevador.', 0, 'San Justo, Buenos Aires', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 14:38:52', '10-04-2026 15:20:24', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 3, 2638, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_515278_bum_vb209f722.jpg', 0, 0, NULL, 70, 'Avisos Classic', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179044.html', '2026-04-13T07:05:55.103735');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227915, 319880, 'Analista de calidad', 'Randstad Argentina', '¡Esta propuesta te puede interesar! En esta oportunidad, nos encontramos en la búsqueda de Analistas de Calidad para incorporarse de manera inmediata y bajo contratación efectiva al equipo de una reconocida e importante empresa del rubro perfumista ubicada en el Parque Industrial de Garín. La posición está orientada a personas con secundario completo que posean una marcada orientación al detalle y compromiso con las normas de seguridad e higiene. ¡Si sos Técnico o Técnica Química, te invitamos especialmente a postularte! El rol requiere disponibilidad para trabajar en horarios rotativos y ofrece excelentes beneficios, entre los que se destacan el servicio de comedor en planta y la entrega mensual de una caja con productos exclusivos de la marca. Si buscás estabilidad laboral en una compañía líder y contás con formación técnica, ¡esta es tu oportunidad de crecer en el sector! Si consideras que reunís los requisitos para el puesto y te gustan los desafíos, no lo dudes…. ¡Postulate! Sobre Randstad En Randstad nos moviliza ayudar a las personas y a las organizaciones a desarrollar todo su potencial. Ese es el compromiso que asumimos como compañía en todo el mundo, un compromiso que nos impulsa a ir más allá para lograr que nuestros clientes y candidatos alcancen el éxito. ¿Cómo lo hacemos?, combinando nuestra pasión por las personas con el poder de la tecnología, creando experiencias más humanas, que nos permitan ser una fuente de inspiración y apoyo para quienes nos eligen. Porque estamos convencidos de que mejores personas hacen mejores. ¡Esta propuesta te puede interesar! En Randstad nos moviliza ayudar a las personas y a las organizaciones a desarrollar todo su potencial. Ese es el compromiso que asumimos como compañía en todo el mundo, un compromiso que nos impulsa a ir más allá para lograr que nuestros clientes y candidatos alcancen el éxito. ¿Cómo lo hacemos?, combinando nuestra pasión por las personas con el poder de la tecnología, creando experiencias más humanas, que nos permitan ser una fuente de inspiración y apoyo para quienes nos eligen. Porque estamos convencidos de que mejores personas hacen mejores empresas. // Agregar texto de la oportunidad laboral // Si consideras que reunís los requisitos para el puesto y te gustan los desafíos, no lo dudes…. ¡Envíanos tu CV!', 0, 'Tortuguitas, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 20:46:56', '13-04-2026 04:05:09', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 16, 84, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_319880_bum_vff58225f.jpg', 1, 0, 4.28, 70, 'Simples', 'bumeran', 'simple', 1, 0, 1, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227915.html', '2026-04-13T07:05:55.103933');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226887, 10093977, 'Analista Contable', 'BML Collection Services', 'Nos encontramos en la búsqueda de un/a Analista Contable para incorporarse al equipo de Administración y Finanzas. La posición tendrá un rol clave en el control, registración y análisis de la información contable de la compañía.Principales responsabilidades Análisis, registración y conciliación de cuentas contables. Registro de movimientos económicos, ingresos y egresos. Análisis de cuentas patrimoniales y cuentas corrientes de proveedores y clientes. Gestión integral de cuentas a pagar: Control, registro y archivo de facturas. Coordinación de pagos según flujo de caja. Emisión de transferencias, cheques y órdenes de pago. Cálculo de retenciones impositivas. Gestión de facturación: Emisión de facturas a clientes. Control y validación de solicitudes de facturación. Ingreso a portales de Clientes Registro contable de la facturación. Registro de cobranzas y depósitos bancarios. Conciliaciones bancarias y de fondo fijo. Armado de documentación para transferencias locales y al exterior. Atención y seguimiento de proveedores. Archivo y organización de documentación contable. Soporte a requerimientos de otras áreas.Requisitos Estudiante intermedio/avanzado o graduado de Contador Público o Administración de Empresas. Experiencia comprobable* en posiciones contables (mínimo 2 años excluyente). Conocimientos en: Conciliaciones contables Facturación Cuentas a pagar y cobrar Manejo de sistemas contables Manejo de Excel (nivel intermedio/avanzado). Conocimiento básico/intermedio en impuestos y portales fiscales (deseable).(*) realizaremos un test de conocimientos para la posición.Perfil buscado Fuerte orientación al detalle y prolijidad. Buen nivel analítico. Organización y capacidad de planificación. Compromiso y responsabilidad. Buen manejo de relaciones interpersonales. Orientación a resultados.Características del puesto: Posición efectiva Sueldo acorde a posición, Convenio Comercio. Zona de trabajo: Tribunales Horario de trabajo: full time – Hibrido Prepaga de primer nivel.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '10-04-2026', '10-04-2026 13:13:57', '12-04-2026 16:40:04', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_10093977_bum_v64c077eb.jpg', 0, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226887.html', '2026-04-13T07:05:55.104084');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226471, 10095460, 'Analista de Procesos', 'Neo-Biz', 'Fundemap es una empresa dedicada a la fundición y al mecanizado de piezas de aluminio. Analista de ProcesosNos encontramos en la búsqueda de un/a Analista de Procesos para nuestro cliente FUNDEMAP, orientado/a a profesionales con sólida capacidad analítica, enfoque en resultados y experiencia en entornos productivos.La posición está dirigida a quienes busquen desarrollarse en un entorno industrial dinámico, aportando valor a través de la mejora continua y la optimización de procesos.Misión del rolSerá responsable de analizar, optimizar y estandarizar los procesos productivos, asegurando niveles adecuados de eficiencia, calidad y cumplimiento de estándares.Su gestión tendrá impacto directo en la mejora de la productividad, la reducción de desperdicios y la consolidación de prácticas de mejora continua en planta. Principales responsabilidades Analizar procesos productivos e identificar oportunidades de mejora Realizar estudios de métodos y tiempos Detectar desvíos, cuellos de botella e ineficiencias Implementar mejoras y asegurar la estandarización de procesos Monitorear indicadores de gestión (productividad, calidad y costos) Analizar no conformidades y definir acciones correctivas Participar en auditorías internas y cumplimiento normativo Elaborar y mantener documentación técnica de procesos Trabajar de manera transversal con Producción, Calidad, Ingeniería y Mantenimiento Promover una cultura de mejora continua en planta Requisitos Formación en Ingeniería Industrial, Mecánica o carreras afines (deseable) Experiencia mínima de 2 años en posiciones similares en industria Conocimiento en metodologías de mejora continua (Lean, Six Sigma, Kaizen) Manejo de herramientas de análisis de procesos, tiempos y métodos Experiencia en seguimiento de KPIs y análisis de datos Conocimiento de normas de calidad (IATF, ISO) Manejo de office, ERP y CAD excluyente San Lorenzo | Jornada full time Requisitos:', 0, 'San Lorenzo, Santa Fe', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 09:21:12', '10-04-2026 09:21:12', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 30, 2581, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_10095460_bum_v946b7462.jpg', 1, 0, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226471.html', '2026-04-13T07:05:55.104220');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227030, 13181155, 'Analista de Compras', 'IC Consultora', 'Para importante organización, nos encontramos en la búsqueda de un/a Analista de Compras para sumarse al equipo.La posición tiene como objetivo brindar soporte operativo y analítico al área, colaborando en la gestión de compras, seguimiento de proveedores y asegurando el abastecimiento oportuno de insumos, en línea con los procedimientos establecidos.Responsabilidades principales: Solicitar y analizar cotizaciones de proveedores. Cargar y gestionar órdenes de compra en sistema. Realizar el seguimiento de pedidos hasta su recepción. Verificar la correcta recepción de materiales (cantidad y calidad). Gestionar reclamos y devoluciones a proveedores. Mantener actualizada la información de proveedores y precios. Colaborar en la elaboración de reportes e indicadores del área. Brindar soporte administrativo general al sector. Requisitos: Experiencia de 1 a 2 años en áreas de compras, administración o abastecimiento. Estudiante o graduado/a de carreras como Administración, Comercio o afines. Manejo de Microsoft Excel (nivel intermedio). Conocimientos de SAP (deseable). Perfil analítico, ordenado y responsable. Buenas habilidades interpersonales, trabajo en equipo y orientación a resultados. Beneficios Posibilidades de desarrollo profesional. Excelente clima de trabajo. Condiciones de contratación acordes al mercado.Si te interesa la propuesta y cumplís con los requisitos, ¡te invitamos a postularte!IC Consultora de RRHHAcompañamos el crecimiento de empresas y personas, generando oportunidades de valor.', 0, 'Belén de Escobar, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 14:15:35', '10-04-2026 14:15:35', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, NULL, 1, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227030.html', '2026-04-13T07:05:55.104352');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225498, 10174570, 'Analista Financiero', 'Avis Budget Argentina', 'Avis Budget Argentina, empresa líder de alquiler de vehículos, seleccionará para su casa central un Analista Financiero.Las tareas principales serán: Confección de presupuestos Cierres Control de ejecución presupuestaria Reportes variosNos orientamos a un perfil proactivo, resolutivo, y que le interese desarrollarse en un entorno dinámico y desafiante. Requisitos excluyentes: Manejo avanzado de Excel Lic. en Adminsitración de Empresas, Contador Público Nacional, o afines Dos años o más de experiencia en posiciones similaresOfrecemos interesantes condiciones decontratación y beneficios.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 14:40:52', '09-04-2026 15:03:56', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 1, 25, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_10174570_bum_vfa015b9b.jpg', 1, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225498.html', '2026-04-13T07:05:55.104457');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225393, 1118240, 'ANALISTA DE COMPRAS', 'Cubi HR', 'En CUBI HR – Capacidad de Conectar® nos encontramos en la búsqueda de un Analista de Compras para sumarse al equipo de un importante cliente con una sólida trayectoria en el mercado. Principales responsabilidades del rol:Gestionar de forma integral el proceso de compras productivas y no productivas, cumpliendo con los procedimientos establecidos a fin de obtener los insumos y bienes en las mejores condiciones de precios, calidad y oportunidad. Recibir y analizar cotizaciones de proveedores de acuerdo a requisiciones. Gestionar registro de proveedores. Realizar órdenes de compra. Verificar materiales y equipos adquiridos. Requisitos: Profesionales o estudiantes avanzados en las carreras de Ingeniería / Adm. de Empresas Experiencia previa de 1 ó 2 años Excel / Paquete de Office intermedio-avanzado Experiencia en SAP / Conocimientos en Power BI Herramientas de simulación, probabilidad, estadística Residir en La Plata o alrededores Jornada: Lunes a Viernes de 8:30 a 17:00 hs Lugar de Trabajo: La Plata Beneficios Prepaga de primer nivel Almuerzo: Comedor en Planta Día del cumpleaños libre Kit escolar', 0, 'La Plata, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 14:01:55', '09-04-2026 14:01:55', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 22, 36, 1, NULL, 0, 0, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225393.html', '2026-04-13T07:05:55.104581');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225018, 13483520, 'Analista de Auditoría', 'Gisel Leone', 'Analista de Auditoría Resumen del Puesto Nos encontramos en la búsqueda de un Analista de Auditoría para integrarse a un equipo profesional. El rol implica la ejecución de tareas de auditoría y análisis financiero, asegurando el cumplimiento normativo y la identificación de oportunidades de mejora. Responsabilidades Elaboración de estados contables y certificaciones. Realización de pruebas sustantivas de auditoría. Preparación de presentaciones regulatorias. Análisis de información financiera y operativa. Evaluación del cumplimiento de normas contables, fiscales y regulatorias. Identificación de riesgos, desviaciones y oportunidades de mejora. Preparación de borradores de informes de auditoría. Seguimiento de observaciones y planes de acción. Requisitos Estudiante avanzado o graduado de Contador Público. Experiencia previa en puestos similares de al menos 2 años (excluyente). Sólidas habilidades analíticas y de resolución de problemas. Capacidad para trabajar de forma autónoma y colaborativa. Conocimiento de normativas contables, fiscales y regulatorias. Se ofrece Relación de dependencia. Oportunidades de desarrollo profesional. Modalidad de trabajo mixta. Condiciones de contratación competitivas.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 11:58:14', '10-04-2026 14:11:51', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 1, 83, 1, NULL, NULL, NULL, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225018.html', '2026-04-13T07:05:55.104696');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223864, 2330920, 'Analista Funcional', 'HELIOS SALUD', '🚀 Búsqueda Laboral: Analista Funcional ¿Te apasiona ser el puente entre las necesidades del negocio y la tecnología? ¡Te estamos buscando! Nos encontramos en la búsqueda de un Analista Funcional para sumarse a nuestro equipo en San Telmo, CABA.🎯 El DesafíoTu objetivo será relevar, analizar y traducir las necesidades del negocio en soluciones tecnológicas robustas, asegurando la evolución e integración de nuestros sistemas y actuando como nexo estratégico entre las áreas operativas y el equipo de IT.📝 Responsabilidades Principales Análisis y Relevamiento: Detectar oportunidades de mejora en procesos actuales y documentar requerimientos funcionales/casos de uso. Gestión de Aplicaciones: Administrar el soporte funcional, validar cambios y participar en la implementación de nuevos sistemas. Gestión de Stakeholders: Traducir necesidades de negocio a lenguaje técnico y acompañar a los usuarios en la adopción de nuevas herramientas. QA & Testing: Definir y ejecutar pruebas funcionales para asegurar que cada entrega cumpla con los estándares de calidad. Mejora Continua: Proponer automatizaciones y mantener actualizada la documentación técnica y manuales de usuario.⚙️ Requisitos del Perfil Formación: Estudiante avanzado o graduado en Sistemas o carreras afines. Experiencia: Mínimo de 2 años en posiciones similares. Hard Skills: Experiencia sólida en análisis funcional y relevamiento de requerimientos. Dominio de documentación funcional y testing de aplicaciones. Conocimientos Valorados (Plus): Manejo de sistemas de gestión (ERP, salud o administrativos). Bases de datos (SQL nivel básico/intermedio). Nociones de integraciones (APIs, Web Services).📍 Condiciones de Trabajo Ubicación: San Telmo, CABA. Modalidad: 100% Presencial. Horario: Lunes a Viernes de 09:00 a 18:00 hs.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 15:45:55', '10-04-2026 09:53:57', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2618, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2330920_bum_v2c35e74c.jpg', 1, 0, NULL, 70, 'Simples', 'bumeran', 'tecnologia', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223864.html', '2026-04-13T07:05:55.104873');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223905, 13381134, 'Analista de Licitaciones', 'IngeJons', 'Nos encargamos del proceso de búsqueda, selección y contratación de personal técnico para fabricas y empresas de ingeniería. Realizamos procesos de evaluación técnica de acuerdo a las necesidades del puesto a cubrir. Cubrimos posiciones para diferentes niveles en áreas de Producción, Mantenimiento, Calidad, Operaciones, Procesos, ingeniería, Supply Chain, Customer Service, Logística, Seguridad & Higiene, Compras y Ventas Técnicas. Importante empresa dedicada a la importación, fabricación y distribución de insumos odontológicos incorpora un Analista de Licitaciones.Tendrá como objetivo gestionar el proceso de licitaciones de punta a punta, garantizando el cumplimiento técnico-administrativo y actuando como nexo con los organismos para asegurar la eficacia en las adjudicaciones.Nos orientamos a perfiles con una marcada atención al detalle, prolijidad y autonomía, que cuenten con una fuerte capacidad organizativa para la gestión integral de procesos. ️ Principales responsabilidades Gestionar el proceso de licitaciones de punta a punta, desde la búsqueda de oportunidades hasta la adjudicación. Analizar pliegos detalladamente para garantizar el cumplimiento de requisitos técnicos, administrativos y fechas inamovibles. Operar de forma experta las plataformas BAC y Comprar (carga de ofertas, seguimiento y facturación). Coordinar con logística la entrega de muestras, remitos y productos en instituciones públicas y privadas (Hospitales, Facultades). Administrar la carga de facturas en el sistema interno y realizar el seguimiento de cobranza y retenciones. Evaluar los resultados de las aperturas de sobres y precios de la competencia para proponer mejoras estratégicas. Colaborar con la Gerencia Comercial y Dueños en la definición de precios y lineamientos de ventas. Requisitos Formación: Estudiante o graduado de Cs. Económicas o Administración de Empresas (preferente). Experiencia: Mínimo 2 años en posiciones similares de gestión de licitaciones. Plataformas: Manejo avanzado de BAC (GCBA) y Comprar (Nación). Herramientas: Dominio de paquete Office, con foco en Excel para gestión de precios y comparativas. Normativas: Conocimiento de normas ISO y GMP (deseable). Horario: Lunes a viernes de 08 a 17:30 hs (100% presencial). Residencia: CABA (excluyente). Requisitos:', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 16:05:59', '08-04-2026 16:05:59', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 1, 2594, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223905.html', '2026-04-13T07:05:55.105045');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118221783, 13155237, 'Analista Impositivo', 'PARADA FLAVIA DANIELA', 'Analista Impositivo Resumen del Puesto Buscamos un Analista Impositivo para unirse a nuestro equipo contable. El candidato ideal tendrá un fuerte conocimiento de las normativas impositivas y será capaz de trabajar de forma autónoma y proactiva. Responsabilidades Clave Ejecución, control y análisis del ciclo impositivo mensual y anual. Manejo de plataformas fiscales con total autonomía. Liquidación integral de impuestos nacionales y provinciales (IVA, IIBB, Tasas Municipales). Gestión y presentación de regímenes de retención y percepción. Conciliación de cuentas contables e impositivas. Preparación de documentación técnica para auditorías y respuesta a requerimientos de entes reguladores. Requisitos Estudiante de Contador Público o carreras afines. Sólido conocimiento de las normativas impositivas. Capacidad para trabajar de forma autónoma y proactiva. Excelentes habilidades analíticas y de resolución de problemas. Capacidad para trabajar de forma independiente y como parte de un equipo. Excelentes habilidades de comunicación escrita y verbal.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 15:58:10', '09-04-2026 13:50:01', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 1, 90, 1, NULL, 0, 0, NULL, 750, 'Aviso Express', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221783.html', '2026-04-13T07:05:55.105179');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118221905, 13019167, 'Analista de Tesoreria', 'La Mantovana SGSA', 'Imporante empresa de del rubro facility, incorpora estudiantes avanzados o recientemente graduados en carreras de Ciencias Economicas para desempeñarse como analista en el area de tesoreria.Deberan poseer experiencia previa en el puesto no inferior a dos años como asi tambien con excelente manejo de paquete office.Entre sus funciones se destacan carga de ordenes de pago en el sistema, pago y tranferencias bancarias, analisis de cuentas corrientes, contabilizacion de operaciones y conciliaciones, colaboracion en armado de cashflow y reportes de festion. Brindara soporte al sector segun las necesidades del mismo como asi tambien tendra contacto y comunicacion directa con otras areas de la empresa.Valoraremos la capacidad de organizacion y planificacion, orientacion a resultados, adaptabilidad al cambio, capacidad resolutiva y comunicativa.Invitamos a aquellos interesados a postularse con cv actualizado y sueldo estimado.Incorporacion inmediata.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '07-04-2026', '07-04-2026 16:00:59', '09-04-2026 11:54:27', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 1, 2597, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/1/3/0/1/9/1/6/7/logoMainPic_13019167_bum_ve9552771.jpg', 0, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221905.html', '2026-04-13T07:05:55.105306');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118220141, 327430, 'Analista de Administración', 'LOMA NEGRA C.I.A.S.A.', 'Ferrosur Roca S.A., compañía ferroviaria del Grupo Loma Negra, brinda servicios de transporte de cargas y opera la concesión del Ferrocarril General Roca desde 1993. Su red ferroviaria conecta los principales polos productivos de las provincias de Buenos Aires y Neuquén, integrando puertos y centros de consumo, y transporta principalmente cemento, áridos y productos químicos. Misión:Brindar soporte de gestión a la Gerencia Comercial y a las unidades de la compañía mediante la ejecución y análisis de procesos administrativos, asegurando el cumplimiento de políticas y procedimientos internos, la optimización de los recursos y la generación de información confiable para la toma de decisiones. Sus principales responsabilidades: Elaborar reportes periódicos de gastos, desvíos y KPIs del área, dando soporte a la gestión administrativa y operativa. Analizar desvíos y proponer acciones para optimizar los indicadores a su cargo. Elaborar proyecciones de Cash Flow. Colaborar en el análisis de indicadores de rentabilidad y costos por negocio y/o cliente. Analizar tendencias de costos, gastos operativos y compromisos financieros Proponer mejoras en los procesos administrativos y financieros. Dar soporte a la gestión comercial mediante el análisis de KPIs, CMg, S&OP y procesos para la toma de decisiones. Requisitos: Formación:Estudiantes/graduados de las carreras de Contador Público, Administración de Empresas, Comercialización o afines (excluyente) Experiencia:Experiencia en tareas administrativas, gestión financiera, atención al cliente, análisis de cuentas (deseable) Herramientas: Manejo avanzado de Excel, Word, Power Point (excluyente) Conocimiento en Power BI o herramientas de análisis de datos (deseable) Conocimiento en SAP (deseable) Manejo de herramientas de IA: Copiliot, ChatGPT (deseable) Conocimiento de Metodología de Mejora Continua (deseable) Competencias: Capacidad analítica, proactividad y orientación a resultados Trabajo en equipo y Atención al clliente Manejo de relaciones interpersonales Beneficios Lugar de trabajo: Puerto Madero, CABA​ Modalidad: 4 días presenciales + 1 remoto', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '06-04-2026', '06-04-2026 16:13:17', '06-04-2026 16:13:17', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/0/0/3/2/7/4/3/0/logoMainPic_327430.jpg', 0, 0, NULL, 40, 'Destacados', 'bumeran', 'destacado', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118220141.html', '2026-04-13T07:05:55.105486');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179057, NULL, 'ANALISTA CREDITOS Y COBRANZAS', 'Confidencial', 'Importante Industria Plástica de producción envases flexibles zona Bella Vista (San Miguel) GBAComo Analista de Créditos y Cobranzas en nuestra empresa, serás responsable de realizar el seguimiento de las cuentas corrientes de los clientes, mantener registros precisos y reclamar el pago de las facturas vencidas para garantizar de forma exitosa y rápida el cobro de las mismas, así como también evitar o minimizar la morosidad para mantener el flujo de caja y liquidez de la empresa.Este es un puesto de tiempo completo que se desempeñará de manera presencial en la zona de Gran Buenos Aires.Responsabilidades: Seguimiento de vencimientos de facturas para gestionar los pagos de las mismas. Gestión integral de cobranzas; ingreso de recibos al sistema con seguimiento a las cuentas corrientes. Armado de planillas Excel para seguir la agenda de cobranzas, cheques rechazados y ajustes en cuentas corrientes. Reporte diario al gerente de Ventas y seguimiento a vendedores. Organización y administración de la agenda de cobranzas, atención telefónica y vía mail, incluyendo derivación de consultas de clientes y proveedores a otros sectores. Control de cuentas corrientes y conciliaciones de las mismas. Análisis de riesgo crediticio de los clientes solicitados por la Gerencia. Paquete office nivel avanzado. Dominio del sistema de contabilidad (Pref. Arise). Área de estudio: Admin. De Empresas, Contabilidad o Finanzas (pref). Experiencia deseada en empresas industriales.Se valorarán candidatos con capacidad de análisis financiero y de datos, gestión de cobros y relaciones con clientes.Requisitos: Paquete office nivel avanzado. Dominio del sistema de contabilidad (Pref. Arise). Área de estudio: Admin. De Empresas, Contabilidad o Finanzas (pref). Experiencia deseada en empresas industriales.Se valorarán candidatos con capacidad de análisis financiero y de datos, gestión de cobros y relaciones con clientes.Si querés ser parte de nuestro equipo, envianos tu CV. con foto, sin omitir remuneración bruta pretendida.', 1, 'Bella Vista, Buenos Aires', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 15:26:30', '10-04-2026 08:42:09', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 1, 2592, 1, NULL, NULL, NULL, NULL, 70, 'Avisos Classic', 'zonajobs', 'zonajobs', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179057.html', '2026-04-13T07:05:55.105635');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118219795, 13104662, 'Analista de research y base de datos', 'Generalistas', 'Atención:La posición es 4 días presencial en Pilar y 1 día remoto (viernes).Nos encontramos en la búsqueda de un/a Analista Financiero Jr. para incorporarse a una compañía del sector de inversiones y financiamiento.Requisitos excluyentes: Estudiante avanzado/a o graduado/a en Ciencias Económicas o afines. Manejo avanzado de Excel. Interés y conocimientos básicos en productos financieros. Disponibilidad para trabajar presencialmente en Pilar 4 días por semana (deseable con movilidad propia)Condiciones: Jornada full time ( 9 a 1 8 hs). Esquema híbrido: 4 presencial + viernes remoto. OSDE (plan individual). Día libre por cumpleaños.Responsabilidades principales: Seguimiento de variables económicas y financieras. Elaboración de reportes de mercado y análisis de activos. Armado y actualización de bases de datos y tableros de control. Carga y análisis de EECC, flujos proyectados e indicadores financieros. Soporte al control de riesgos y colaboración con el equipo comercialSi cumplís con los requisitos y la modalidad es viable para vos, esperamos tu postulación.', 0, 'Pilar, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 11:47:27', '08-04-2026 11:47:27', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 1, 2599, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13104662_bum_v5bfaa67e.jpg', 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118219795.html', '2026-04-13T07:05:55.105761');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118228422, 1476590, 'Analista Funcional Implementador Odoo (San Martín)', 'Zivot Consultora en RH', 'Empresa de Servicios ubicada en San Martín, incorpora Analista Funcional para implementación Sistema Odoo, con una experiencia mínima de 3 años en posiciones similares.Tareas / Conocimientos- Liderar implementación de Odoo, relevando procesos y configurando soluciones funcionales.- Escalar requerimientos cuando se necesiten desarrollos o ajustes avanzados.- Controlar uso del sistema en la empresa y proponer mejoras.- Analizar flujos de trabajo y configurar en el sistema.- Crear guías de usuario, capacitar al personal y atender consultas de usuarios finales.- Mejorar los procesos en el marco de implementación del ERP, efectuando pruebas de calidad y mejora.- Elaborar documentación funcional y requerimientos y analizar integraciones y datos.-Requisitos- Estudiante o recibido de carreras de Sistemas o afines ala necesidad de la posición.- Experiencia de 3 años en implementación de ERP (preferentemente Odoo).Horario de Trabajo: Lunes a Viernes de 8.00 a 17.00 hs.Se ofrece trabajo directo por la empresa, sueldo acorde, prepaga, comedor y bono anual.', 0, 'San Martin, Buenos Aires', 'Presencial', 'Full-time', '12-04-2026', '12-04-2026 11:35:12', '12-04-2026 11:35:12', '2026-04-12', NULL, NULL, '2026-04-12T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2618, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/0/1/4/7/6/5/9/0/logoMainPic_1476590.jpg', 0, 0, 4.85, 1020, 'Aviso Talento', 'bumeran', 'tecnologia', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118228422.html', '2026-04-13T07:05:55.105886');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226945, 13379526, 'ANALISTA DE PROCESOS E INTELIGENCIA ARTIFICIAL JR.', 'HOLZBODEN', 'Especialista en Automatización y Productividad con Inteligencia ArtificialResumen del PuestoBuscamos un profesional innovador y proactivo, apasionado por la tecnología, orientado a aplicar la IA (Inteligencia Artificial) en la optimización de procesos diarios de trabajo.Si te entusiasma dominar las herramientas más modernas y aplicarlas para revolucionar la eficiencia operativa, este rol es para ti.Estudios: Informatica, sistemas o similar, puede ser en curso.Puesto: Horario Part time a coordinarHibrido o 100% remoto si residis fuera de AmbaLugar de trabajo: Palermo, CABA.ResponsabilidadesIdentificar y transformar procesos manuales o lentos en flujos de trabajo automatizados utilizando soluciones de IA. Configurar, administrar y optimizar software de última generación para mejorar la productividad y automatizar tareas Investigar y mantener al equipo a la vanguardia de las nuevas herramientas y tecnologías emergentes en el mercado. Desarrollar estrategias para maximizar la productividad a través de la aplicación inteligente de la IA. No hace falta que sea un perfil senior con experiencia, mientras tengas conocimientos y demuestres capacidad e interés por aprender y resolver.Requisitos Dominio de herramientas de análisis de datos y plataformas de automatización. Manejo de CLAUDE, CHAT GPT y Gemini. Se valorarán perfiles con experiencia en programación Mentalidad resolutiva y capacidad para encontrar soluciones creativas, incluyendo la integración de nuevas herramientas o el desarrollo de soluciones personalizadas cuando sea necesario. Fuerte capacidad analítica y de resolución de problemas. Proactividad y deseo de aprendizaje continuo en el ámbito de la IA y la tecnología.¿Te apasiona la tecnología? ¿Sabes cómo hacer que la IA trabaje para vos y no al revés? Estamos buscando a alguien que domine los programas más modernos y quiera revolucionar nuestra forma de trabajar. ¿Qué vas a hacer? Transformar procesos lentos en flujos automatizados con IA. Configurar y administrar software de última generación. Mantenernos a la vanguardia de cada nueva herramienta que sale al mercado. ¿Qué buscamos? Alguien que no solo use IA, sino que sepa "hackear" la productividad con ella. Manejo de herramientas de generación de contenido, análisis de datos y automatización. Mentalidad resolutiva: si el programa no existe, buscás la forma de integrarlo.', 0, 'Capital Federal, Buenos Aires', 'Remoto', 'Part-time', '10-04-2026', '10-04-2026 13:35:20', '12-04-2026 09:27:15', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 19, 105, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13379526_bum_v8bf35b69.jpg', 0, 0, NULL, 40, 'Destacados', 'bumeran', 'tecnologia', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226945.html', '2026-04-13T07:05:55.106047');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2178978, 55446, 'Analista Funcional y de Procesos', 'Capital Humano', 'Capital Humano se encuentra en la búsqueda de un/a Analista Funcional y de Procesos para incorporarse a un importante laboratorio veterinario 🧪🐾¿Cuál va a ser tu desafío? 🚀Impulsar iniciativas de mejora de procesos, digitalización y automatización en toda la organización. Relevar, analizar y documentar procesos, detectando oportunidades de eficiencia y optimización. Actuar como nexo entre las áreas de negocio, sistemas y proveedores tecnológicos. Implementar y optimizar herramientas digitales y soluciones de información. Asegurar la calidad, consistencia y disponibilidad de la información para la gestión. Acompañar a los usuarios en la adopción de nuevos procesos y herramientas 📍 Zona de trabajo: Vicente López 🕒 Horario: Lunes a viernes de 8 a 17 hs | Presencial (1 HO semanal)¿Qué buscamos? 🔍Estudiantes o graduados/as de Administración de Empresas, Ingeniería, Sistemas o afines. +3 años de experiencia en roles similares Manejo de ERP (excluyente) Inglés intermedio / avanzado Conocimientos en herramientas de BI (reporting y tableros de gestión) Experiencia en automatización y digitalización de procesos Perfil autónomo, dinámico, con excelentes habilidades interpersonales y mirada estratégica¿Qué ofrece la empresa? 🎁 Medicina prepaga Licencias extendidas Almuerzo Ajustes salariales por Convenio de SanidadUn entorno profesional con foco en la mejora continua y la innovación', 0, 'Vicente López, Buenos Aires', 'Híbrido', 'Full-time', '07-04-2026', '07-04-2026 08:13:09', '10-04-2026 14:42:29', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 30, 2630, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_55446_bum_v5bb1450f.jpg', 1, 0, NULL, 1020, 'Aviso Select', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2178978.html', '2026-04-13T07:05:55.106187');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224336, 1282780, 'Analista de RRHH generalista General Pico La Pampa', 'Adecco - Permanent Talent', 'BUSCAMOS TALENTOS, ¡EN ADECCO TE ESTAMOS BUSCANDO!Si te interesa desarrollarte como Analista generalista de RRHH en General Pico, La Pampa, dentro del equipo de nuestro IMPORTANTE CLIENTE, una empresa del rubro agro–logística–energía, ¡desafíate a vos mismo y creá tu futuro!✅ ¿QUÉ DESAFÍOS TE ESPERAN? Llevar adelante el proceso de selección completo. Gestionar la administración de personal. Realizar el seguimiento de desempeño y acompañar a los líderes en la asignación de tareas. Controlar horarios, ausencias y llegadas tarde. Verificar el uso correcto de EPP y realizar pedidos de los mismos eventualmente. Colaborar con la organización de eventos internos. Profesionalizar y ordenar los procesos del área en una empresa en crecimiento.✅ ¿QUÉ VALORAMOS DE TU PERFIL? Formación en Recursos Humanos o afines (deseable). Experiencia previa en áreas generalistas de RRHH, idealmente en pymes industriales, logísticas, agro o comercios con dotaciones pequeñas. Buen manejo de relaciones interpersonales y comunicación clara. Organización, autonomía y criterio para la gestión diaria. Contar con carnet de conducir (excluyente)✅ ¿QUÉ TE OFRECEMOS? Modalidad: Presencial. Horario:Lunes a viernes de 8 a 12 y 14 a 18 hs. Sábados de 8 a 12:30 hs. Lugar de trabajo: General Pico, La Pampa Cobertura médica: Obra Social¡REGÍSTRATE EN ADECCO EMPLEO Y DA EL PASO QUE NECESITAS! Somos Adecco Argentina una compañía con más de 30 años de experiencia que conecta empresas con talentos, brindando soluciones integrales de Recursos Humanos y buscamos talentos, ¡COMO VOS! Nuestro compromiso, es la #diversidad e #igualdad de oportunidades somos una empresa inclusiva. Cuando sos parte de nuestros procesos, solo cuentan tus méritos, logros y capacidades, lo hacemos pensando en vos como persona. Participar de nuestros procesos de selección no tiene ningún costo para vos candidato/a, trabajar con vos es parte de nuestro compromiso y tarea con la comunidad. Postulate y participa en una oferta de empleo nuestra. El empleador sólo podrá solicitarle la información estrictamente necesaria para el desempeño en el trabajo que se ofrece.Ciudad de Buenos Aires: ley de búsqueda laboral equitativa - Ley 6471', 0, 'General Pico, La Pampa', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 19:03:04', '10-04-2026 18:59:42', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 17, 48, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/0/1/2/8/2/7/8/0/logoMainPic_1282780_bum_vf37880d6.jpg', 0, 0, 3.73, 70, 'Simples', 'bumeran', 'simple', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224336.html', '2026-04-13T07:05:55.106358');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2178977, 376754, 'Analista en sistemas de redes y telecomunicaciones', 'FV SA', 'Te invitamos a ser parte de una compañía líder con una cultura orientada a las personas, que promueve la sustentabilidad, la innovación y la mejora continua, con tecnología de vanguardia y que cuenta con un equipo de profesionales altamente calificados.¿Cuáles son los principales desafíos que tiene la posición? Atender y resolver las necesidades y/o consultas (incidentes) sobre redes LAN / WAN de la organización, en los tiempos de servicios acordados. Efectuar reclamos a proveedores ante problemas en los servicios prestados por estos o ante la demora en la entrega de productos comprados. Configuración y Monitoreo de Switch LAN Capa 2 y Capa 3. Configuración y Monitoreo de la Red WIFI. Configuración de Telefonía IP, SIP Trunks, ABM de internos, Dar soporte transversal a distintos clientes internos. Manejo de soporte via procesos ITIL. Conocimiento de procesos de gestion de redes.¿A qué perfiles nos vamos a orientar? Experiencia mínima de 3 años en posiciones similares Estudiantes universitarios o graduados, preferentemente en Licenciatura o Ingeniería en Telecomunicaciones o Sistemas Sólidos conocimientos en Redes LAN/WAN - Modelo OSI - Cisco CCNA Nivel 2, Procesos de gestion de redes e ITIL Conocimientos de cableado estructurado y montaje de Racks/Switch/AP (deseable) Inglés: Nivel Intermedio. Nos orientaremos a personas con una fuerte orientación a resultados, con foco en la cadena de valor y al trabajo en equipo.¿Qué te ofrecemos? Excelentes condiciones de contratación. Comedor In Company. Día de cumpleaños. Beneficio en Gimnasios Sport club. Obsequios en fechas especiales. Lic. por Paternidad extendida. Capacitaciones de acuerdo con las necesidades de la posición.La posición tiene su base en Villa Rosa, Partido de Pilar.', 0, 'Vicente López, Buenos Aires', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 07:44:26', '10-04-2026 08:10:25', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 19, 107, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_376754_bum_v751e1991.jpg', 0, 0, NULL, 70, 'Avisos Classic', 'zonajobs', 'zonajobs', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2178977.html', '2026-04-13T07:05:55.106500');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179273, 570364, 'Analista Funcional (Sistemas Back Office / ERP) - Onsite - 1823', 'Aliantec', '¿Qué hace la compañía?Empresa de tecnología con más de 30 años en el mercado, especializada en desarrollo de software y soluciones de transformación digital para grandes organizaciones. Cuenta con presencia en Argentina y se enfoca en optimizar procesos a través de plataformas tecnológicas e innovación. Además, ha sido reconocida como Great Place to Work, destacándose por su cultura colaborativa y su foco en el desarrollo de talento.¿Qué necesitás para ser parte del equipo?A nivel personal: Buscamos personas con ganas de aprender y crecer en equipo. Buena predisposición para el trabajo en equipo. Capacidad colaborativa y buena comunicación. Empatía en el vínculo con otros.A nivel técnico: Experiencia de 4 a 5 años en puestos similares, trabajando con sistemas internos de empresa (ERP). Conocimientos avanzados en SQL. | Excluyente. Conocimientos sólidos de procesos de negocio: Contabilidad, Compras, Tesorería y Facturación. Conocimientos en programación. Estudiantes o graduados de carreras informáticas o afines.¿Qué vas a hacer? Analizar y detectar oportunidades de mejora en los sistemas de gestión (Back Office / ERP). Relevar necesidades vinculadas a módulos de Compras, Cuentas a Cobrar/Pagar,Caja, Contabilidad, RRHH, Ventas y Facturación. Asesorar y capacitar a usuarios sobre los sistemas a implementar. Asegurar el testeo integral de las soluciones y confeccionar la documentación técnica y manuales de usuario.¿Cuál es el desafío de la posición?Como Analista Funcional (Sistemas Back Office / ERP), tendrás como desafío relevar, analizar y diseñar requerimientos adaptativos y correctivos,transformándolos en una solución de valor para el cliente, asegurando la eficiencia de los procesos y el cumplimiento de los estándares de calidad.¿Cuándo y dónde trabajarás?La modalidad es 100% presencial, en las oficinas de nuestro cliente que se encuentran en Puerto Madero, CABA. Trabajarás de lunes a viernes de 9 - 18 hs.¿Qué ofrecen? Relación de dependencia directa. Plataformas de Capacitaciones, certificaciones y descuentos. Día de cumpleaños libre. Licencias extendidas. Días de estudio anuales ilimitados. Prepaga para el empleado y grupo familiar. Plan de carrera personalizado.¿De qué fases consta el proceso de selección?Tendrás una primera entrevista con nuestra Recruiter, Melina Rubio para conocer tus experiencias laborales e intereses. Luego, tendrás 2 instancias de entrevistas con nuestro cliente.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 14:48:43', '09-04-2026 14:48:43', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2618, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_570364_bum_v183b0a04.jpg', 0, 0, NULL, 1020, 'Aviso Select', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179273.html', '2026-04-13T07:05:55.106654');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225714, 13499123, 'Process Analyst', 'Medlife', 'MEDLIFE is a non-profit organization that partners with low-income communities in Latin America and Africa to improve their access to medicine, education, and community development projects. Our mission is to build a worldwide Movement empowering the poor in their fight for equal access to healthcare, education, and a safe home. Our vision is a world free from the constraints of poverty. MEDLIFE works with students from around the world to broaden their perspectives and better equip them to advocate for social justice. Resumen del puestoBuscamos un/a Process Analyst para Marketing & Sales que mapée, estandarice y optimice procesos para mejorar la ejecución y la escalabilidad de nuestras actividades comerciales y de marketing. Trabajarás con equipos de Marketing, Sales y Data para convertir flujos informales o fragmentados en procesos claros, medibles y fáciles de ejecutar.Responsabilidades principales Mapear y documentar procesos end-to-end (lead generation, seguimiento, conversión, etc.). Identificar ineficiencias, brechas y fuentes de inconsistencia en workflows. Diseñar e implementar procesos estandarizados y SOPs. Colaborar con Marketing y Sales para alinear procesos con necesidades operativas. Asegurar que la documentación sea accesible y actualizada para todos los stakeholders. Apoyar la implementación de procesos en herramientas (por ejemplo HubSpot). Mejorar continuamente los workflows con base en feedback y datos de desempeño. Definir y seguir KPIs y métricas de proceso; promover buenas prácticas. Requisitos: Requisitos (indispensables) 1+ año de experiencia en mapeo de procesos, business analysis o roles similares (preferible 2–4 años). Título técnico o universitario en Administración, Ingeniería Industrial, Marketing o afines. Experiencia con equipos de Marketing y/o Ventas. Habilidad para documentar procesos (workflows, SOPs) y usar software de modelado. Conocimientos en herramientas CRM (HubSpot deseable) e integraciones. Capacidad analítica, atención al detalle y buenas habilidades de comunicación. Inglés y español: Inglés avanzado altamente valorado.Deseable Experiencia con métricas y business intelligence (KPIs de proceso). Conocimientos en automatización o RPA / herramientas no-code (valorables). Experiencia previa en ONG u organizaciones internacionales.Herramientas y entorno HubSpot, Google Workspace, software de modelado de procesos. Trabajarás en coordinación con Marketing, Sales y Data Team. Beneficios Qué ofrecemos Modalidad: Remoto. Tipo de contrato: Full time. Salario competitivo acorde al cargo. Beneficios según legislación local y seguro de salud privado (EPS 100% cuando aplique). Flexibilidad y oportunidades de crecimiento.', 0, 'La Matanza, Buenos Aires', 'Remoto', 'Full-time', '09-04-2026', '09-04-2026 16:19:02', '09-04-2026 16:19:02', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2647, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/11/static/logoMainPic_13499123_bum_ved56e295.jpg', NULL, NULL, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'tecnologia', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225714.html', '2026-04-13T07:05:55.106853');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118221308, 466770, 'Senior Analyst Escalations - Customer Care – CABA', 'BAYTON', 'En Bayton nos encontramos en la búsqueda un/a Senior Analyst Escalations - Customer Care para multinacional de servicios financieros.El objetivo principal del puesto es proporcionar soporte de primer nivel para consultas y quejas de clientes en línea con los objetivos de SLA. Resolver las consultas, identificar, evaluar problemas y mantenerse involucrado en la resolución.Es una habilidad necesaria la fluidez en la comunicación verbal, escrita y la capacidad de escucha. Se requiere experiencia previa en atención al cliente, siendo deseable experiencia previa en call center.Tareas principales: Atención de consultas y reclamos de clientes, cumpliendo SLAs. Análisis, resolución y escalamiento de incidentes. Registro y seguimiento de casos. Soporte a requerimientos internos y colaboración en proyectos del área. Cumplimiento de normativas y estándares de calidad en la atención.Requisitos: Contar con PC/Notebook propia Buenas habilidades de comunicación oral y escrita. Experiencia en atención al cliente (deseable call center). Disponibilidad para trabajar por turnos.Conocimientos técnicos valorados: Service Now (gestión y seguimiento de tickets y SLAs). Excel intermedio/avanzado. AS400 (consultas, interpretación de datos y Querys). Microsoft 365 (Outlook, Teams, Sharepoint y OneDrive)Lugar de trabajo, Casa Central, ubicada en CABA – San Nicolas. Modalidad: Híbrida 3x2. Se ofrecen interesantes condiciones de contratación.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '07-04-2026', '07-04-2026 12:30:14', '07-04-2026 12:30:14', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 25, 2571, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_466770_bum_v7cd0e054.jpg', 1, 0, 3.9, 70, 'Simples', 'bumeran', 'simple', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221308.html', '2026-04-13T07:05:55.106993');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2178885, 646821, 'SecDevOps Analyst', 'COELSA', 'Somos la empresa de tecnología responsable de crear las herramientas que necesitás para fluir segura y libremente a través del ecosistema de pagos de hoy y de mañana.Con tecnología enfocada en el sector financiero, somos el motor del ecosistema. Garantizamos, promovemos y sustentamos la transformación digital. Democratizamos el acceso dando inclusión al 100% de las entidades financieras, desde los bancos hasta las fintech.La transformación tecnológica es vertiginosa e imparable, por eso diseñamos las herramientas digitales adecuadas para que todos podamos participar e interactuar en el ecosistema de pagos. Se trate de individuos o de empresas. Y siempre con un servicio de calidad. Sumate y dejá que COELSA te impulse,Si sos una persona inquieta y comprometida.Si te atraen los desafíos.Si querés impactar positivamente en la sociedad.Si buscás una empresa que te impulse, te cuide, te acompañe y te escuche.Si soñás con una propuesta a la medida de tu talento,te queremos en nuestro equipo. Porque compartimos el mismo ADN. En COELSA estamos transformando el ecosistema de pagos. Somos una empresa enfocada en el sector financiero. Diseñamos herramientas digitales, contables e innovadoras que permiten que mayor cantidad de personas y empresas operen en forma sencilla, segura y efectiva. Hacemos posible la circulación del dinero, fomentamos la interoperabilidad y garantizamos el funcionamiento de la cadena de pagos.MisiónIntegrar la seguridad en el ciclo de vida del desarrollo y la aparición de software, asegurando que los sistemas, aplicaciones y servicios sean seguros desde la etapa de diseño hasta la producción. Actúa como puente entre los equipos de desarrollo, operaciones y seguridad para implementar y mantener prácticas de seguridad ágiles en un entorno DevOps.Principales Responsabilidades Diseñar e implementar procesos de seguridad dentro del ciclo de vida de desarrollo. Colaborar con equipos de desarrollo, operaciones y seguridad para garantizar que las mejores prácticas de seguridad se intengren de manera fluida en la aplicaciones y sistemas. Automatizar la implementación de controles de seguridad utilizando CI/CD (integración continua/Despliegue continuo) Realizar análisis de vulnerabilidades de aplicaciones, infraestructura y redes. Aplicar pruebas de seguridad en el software a medida que se desarrolla, incluyendo análisis estático y dinámino de código. Configurar y gestionar herramientas de monitoreo de seguridad para detectar y responder a incidentes de seguridad. Investigar y resolver incidentes de seguridad, proporcionando soporte en la respuesta ante brechas de seguridad. Desarrollar scripts y automatizar tareas de seguridad para mejorar la eficiencia y reducir el riesgo humano. Implementar herramientas de seguridad. Asegurar el cumplimiento de normativas de seguridad y privacidad. Proponer mejoras continuas en los procesos y prácticas de seguridad. Proveer capacitación sobre buenas prácticas de seguridad para los equipos de desarrollo y operaciones. Requisitos: Conocimientos técnicos excluyentes: DevSecOps e integración de seguridad en CI/CD pipelines Escaneo de vulnerabilidades en código y dependencias Revisión de seguridad en pull requests y código fuente Cumplimiento de estándares y compliance desde el pipeline Análisis estático y dinámico de código (SAST/DAST) Seguridad en API REST Beneficios Medicina prepaga para vos y tu grupo familiar. Reintegro de gastos por Home office. Bono anual por cumplimiento de objetivos. Posición híbirda 2 días presenciales y 3 remotos./Remota desde el Interior TCR Viajes Programas de capacitación permanente para acompañar tu desarrollo profesional. Capacitación en idiomas. Día de tu cumpleaños libre, descuentos en distintas marcas, días extras de vacaciones, Gympass, Médico Clínico a disposición.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '06-04-2026', '06-04-2026 06:39:17', '06-04-2026 06:39:17', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 2, 0, 19, 2623, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_646821_bum_vb2938c90.jpg', 0, 0, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2178885.html', '2026-04-13T07:05:55.107213');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225946, NULL, 'Arquitecto/a con Perfil comercial', 'Confidencial', 'ASTS OBRAS ACUSTICAS es Empresa líder en el tratamiento y confort acústico con mas de 20 años en el mercadoNos encontramos en búsqueda de un Arquitecto, Ingeniero, Electromecánico o Diseñador de interiores con experiencia comercial para unirse a nuestro equipo en la zona de Tigre, Buenos Aires, Argentina. En esta posición clave, serás el vínculo operativo diario y directo entre el Cliente y la Empresa. Tu labor principal será realizar actividades comerciales hacia actuales y futuros Distribuidores, así como establecer contacto directo con consumidores finales en situaciones que lo ameriten. Además, estarás a cargo del diseño y seguimiento de acciones comerciales para estimular las ventas de nuestra gama de productos aislantes.Principales tareas: Utilizar técnicas de venta para motivar a los clientes. Desarrollar un profundo conocimiento de nuestros productos y sus características, relacionándolos con las acciones comerciales. Mantente actualizado en tendencias de diseño y novedades del sector. Monitorear el Estado de Cuenta, cantidad de presupuestos vs pedidos, y otras métricas relevantes para analizar y optimizar nuestras acciones comerciales. Analizar estrategias comerciales que permitan cerrar operaciones de manera efectiva. Gestión de descuentos especiales, tiempos de producción personalizados, formas de pago flexibles, entre otros aspectos clave para el éxito del negocio.Si te apasiona la arquitectura, el diseño, y tienes habilidades comerciales excepcionales, ¡queremos conocerte! Únete a nuestro equipo y sé parte de una empresa líder en amoblamientos premium con presencia a nivel nacional. ¡Aplica hoy mismo!Requisitos:Requisitos indispensables Formación técnica base: arquitecto, interiorista, diseñador industrial o formación similar relacionada con arquitectura/diseño. Experiencia comercial demostrable, preferentemente en venta de amoblamiento o rubros afines (muebles/suministros premium). Experiencia supervisando o liderando equipos de venta y/o con gestión de múltiples puntos de venta/distribuidores. Capacidad para interpretar planos y participar en reuniones técnicas/proyectos con estudios o constructoras. Habilidades comerciales sólidas: negociación, análisis de performance, orientación a resultados. Disponibilidad para viajar y visitar distribuidores en región asignada.Requisitos deseables Experiencia previa en roles mixtos técnico-comerciales (representante técnico comercial, ejecutivo de cuentas de muebles, etc.). Conocimiento de marketing digital aplicado a retail . Haber trabajado en tiendas o cadenas del rubro construcción Experiencia gestionando procesos de formación o programas de upskilling para vendedores.Competencias Requeridas: Capacidad Empática, dinamismo y proactividad Buena Dicción y Presencia personal Confiabilidad Organización y gestión del tiempoSe ofrece remuneración acorde con bonos de eficiencia o cumplientos de objetivos, y crecimiento laboral dentro de la Empresa.', 1, 'Rincón de Milberg, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 17:41:52', '12-04-2026 11:45:10', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 2, 0, 4, 2330, 1, NULL, NULL, NULL, NULL, 40, 'Destacados', 'bumeran', 'destacado', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225946.html', '2026-04-13T07:05:55.107417');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118221589, 13473307, 'Arquitecto - Modelador BIM', 'La Celeste', 'Somos una PyME familiar con marcada trayectoria en el mercado Cordobés. Más de 70 años avalan nuestra experiencia y productos. Promovemos el desarrollo y el compromiso, diferenciándonos en los altos estándares de calidad de nuestros productos, conviertiéndonos en líderes del rubro alimenticio.¡Sumate para ser parte de esta gran familia! Estamos en búsqueda de un Arquitecto para incorporarse a nuestro equipo.Serás responsable de garantizar la calidad técnica de los proyectos, desde la documentación hasta su correcta ejecución en la obra, asegurando la coherencia entre el diseño y la construcción.Tus principales tareas serán: Desarrollar planos constructivos y municipales de proyectos residenciales. Modelar y editar tipologías residenciales preestablecidas en Revit. Coordinar avances y entregas con otros miembros del equipo y en conjunto con el Director de Proyecto. Revisiones semanales en obra para coordinar con los jefes de obra y detectar problemas a tiempo. Tareas complementarias para Marketing y Ventas. Requisitos: Para tener éxito en este puesto, buscamos a alguien: Con experiencia de 1 año en puestos similares. Profesional de la carrera de Arquitectura. Conocimientos en Revit - Auto CAD – Sketchup - Photoshop o Illustrator. Se valoran competencias claves como proactividad, responsabilidad, capacidad de trabajo bajo presión y adaptabilidad. Residencia en Córdoba Capital (excluyente).', 0, 'Córdoba, Córdoba', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 13:45:14', '07-04-2026 13:45:14', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 4, 2330, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13473307_bum_v5b082261.jpg', 0, 0, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221589.html', '2026-04-13T07:05:55.107561');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227274, 13227504, 'Asesor', 'SegurÚ - Broker de Seguros', 'No es un trabajo. Es una decisión de vida.En Segurú no estamos buscando empleados. Estamos buscando personas que quieran construir algo grande. 👉 Si estás buscando estabilidad… 👉 Si querés un sueldo fijo y previsible…Este aviso no es para vos.Ahora… Si sentís que estás para más… seguí leyendo. Este desafío es para vos si: ✔️ Estás en un punto de inflexión y querés crecer de verdad ✔️ Tenés mentalidad emprendedora (aunque todavía no la estés explotando) ✔️ Querés que tus ingresos dependan de tu capacidad, no de un convenio colectivo o paritaria. ✔️ Te energiza generar oportunidades y hablar con personas ✔️ No te conformás y buscás superarte constantemente 👉 No buscamos experiencia perfecta. Buscamos actitud, ambición y hambre de crecimiento.¿Qué vas a encontrar en Segurú? 🚀 Plan de carrera real (No promesas. Camino concreto con ingresos escalables) 🎓 Formación profesional (Becas para obtener tu matrícula como Productor Asesor de Seguros) 🏆 Sistema de incentivos (Bonos, premios y reconocimiento por resultados) 👥 Acompañamiento constante (No estás solo: te formamos, te guiamos y te empujamos) 📈 Crecimiento sin techo (Tu límite lo definís vos) 🏢 Empresa sólida + visión de expansión nacionalLa diferencia clave:Acá no venís a “trabajar”. Venís a construir una carrera que puede cambiar tu vida.¿Te interesa?Esto no es para todos. Es para quienes están listos para dar el salto. 👉 Postulate y empezá a construir el futuro que sabés que podés lograr.', 0, 'Mendoza, Mendoza', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 15:56:12', '10-04-2026 15:56:12', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 28, 2410, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13227504_bum_vda5c60f9.jpg', 0, 0, NULL, 750, 'Aviso Express', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227274.html', '2026-04-13T07:05:55.107718');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118156756, 13124663, 'Asesor Comercial', 'RE/MAX Vincit', 'Desde Remax Vincit! Estamos incorporando perfiles emprendedores para formar parte de nuestro equipo de asesores. Vas a contar con una serie de capacitaciones de la mano de tu oficina como de Remax Argentina, donde te vas a formar con profesionales en todas las áreas y con años de trayectoria en el rubro.🧑‍💼 Te proponemos venir a formar un negocio dentro del ámbito de los bienes raíces.💸 Requisitos: ¿Qué buscamos? 🔍 Perfil comercial con buenas relaciones interpersonales y alta vocación de servicio al cliente. Proactividad, con capacidad de administrar cartera de clientes y propiedades. Compromiso con la marca, la oficina y el equipo. Profesionalismo y visión a futuro. Disponibilidad plena para el negocio. Beneficios: ¿Qué ofrecemos? 💎 Ingresos en dólares con las comisiones más altas del mercado. Horario Flexible.Los mejores avances en tecnología e infraestructura en una oficina equipada y funcional. Soporte profesional de martilleros matriculados, abogados, escribanos y contadores, que acompañaran y asistirán tu crecimiento.Capacitaciones constantes para cada etapa de tu carrera.Excelente ambiente laboral y trabajo en equipo. Unite a nuestro equipo e iniciate en el negocio inmobiliario junto a la marca líder en el mundo de negocios inmobiliarios. Sumate, al equipo que MAS VENDE! 🚀 Sumate a Remax Vincit! ❤️🤍💙 Queremos conocerte ¡Esperamos tu postulación!', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '07-04-2026', '07-04-2026 16:05:42', '10-04-2026 18:06:18', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13124663_bum_v9378a0e3.jpg', 0, 0, NULL, 40, 'Destacados', 'bumeran', 'destacado', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118156756.html', '2026-04-13T07:05:55.107866');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118218721, 13435900, 'Asesora de Ventas', 'Foster+Alchemy', 'Asesor/a de VentasResumen del PuestoBuscamos un/a Asesor/a de Ventas con una marcada sensibilidad estética, un profundo interés por el diseño y una genuina pasión por los detalles. El candidato ideal aportará una atención cálida y personalizada, una presencia cuidada y un especial aprecio por el mundo de las fragancias.Responsabilidades Brindar una atención excepcional y personalizada a cada cliente. Asesorar sobre productos, destacando sus cualidades estéticas y de diseño. Gestionar el punto de venta, asegurando una presentación impecable de los productos. Fomentar un ambiente de compra agradable y acogedor. Contribuir al logro de los objetivos comerciales a través de una excelente experiencia de cliente.Requisitos Experiencia previa en roles de atención al cliente o ventas, preferentemente en entornos relacionados con el diseño, la estética o productos de alta gama. Alta capacidad de comunicación y habilidades interpersonales. Vocación de servicio y orientación al cliente. Interés y conocimiento en diseño, estética y tendencias. Proactividad, dinamismo y atención al detalle. Capacidad para trabajar en equipo y de forma autónoma.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '06-04-2026', '06-04-2026 15:19:02', '06-04-2026 15:19:02', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118218721.html', '2026-04-13T07:05:55.107979');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1117998882, 10900, 'Asesor comercial para Neuquén', 'PROSEGUR S.A.', 'Prosegur es un referente global del sector de la seguridad privada. A través de sus cinco líneas de negocio —Prosegur Seguridad, Prosegur Cash, Prosegur Alarmas, Cipher y Prosegur AVOS— proporciona a empresas, hogares y comercios, una seguridad de confianza basada en las soluciones más avanzadas del mercado. Con presencia en los cinco continentes, Prosegur cuenta en la actualidad con un equipo de más de 160.000 empleados. ¿Sos un APASIONADO por las VENTAS? En Prosegur queremos que seas parte del Team Of Teams Comercial. ¿Qué buscamos en vos? Ganas de seguir aprendiendo y motivación, para afrontar nuevos desafíos. Residir en la zona de Neuquen y la Zona Orientación a resultados, para convertir lo bueno en excelente. Innovación, para identificar nuevas oportunidades. Con un espíritu de equipo imparable. Responsable y comprometido con lo que haces. ¿Qué te ofrecemos? Sueldo fijo + Excelentes premios y escala de comisiones, sin techo. Plan de carrera, sujeto a resultados. Plan de formación continuo. Beneficios Corporativos. Muy buen clima laboral La innovación, nuestra pasión Nuestro Propósito: hacer del mundo un lugar más seguro. Y esto lo conseguimos gracias a nuestra apuesta por la innovación, la tecnología y al gran compromiso de nuestros más de 160.000 colaboradores presentes en los 5 continentes. ¿Cómo somos? Nuestro ADN: En Prosegur cuidamos de quienes más nos importan, empezando por nuestro propio equipo. Para ello, compartimos unos valores comunes que nos guían para trabajar con alegría y entusiasmo: NOS IMPORTAN LAS PERSONAS: protegemos los sueños de los demás, motivando a nuestros compañeros a ir más allá. PENSAMOS EN POSITIVO: resaltamos el lado bueno de las cosas y no ponemos “peros”, damos soluciones. SOMOS IMPARABLES: afrontamos cualquier desafío juntos, como un verdadero Team of Teams.', 0, 'Neuquén, Neuquén', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 14:54:29', '10-04-2026 14:54:29', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 5, 0, 6, 23, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_10900_bum_vffbbdb79.jpg', 1, 1, 4.09, 40, 'Destacados', 'bumeran', 'destacado', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1117998882.html', '2026-04-13T07:05:55.108119');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225539, NULL, 'Asesor Comercial-APM', 'Confidencial', 'Importante empresa de fabricación de productos electro médicos está en la búsqueda para su departamento de Marketing de un agente de propaganda médica.Nos orientamos a perfiles comerciales con capacidad tecnica para promocionar productos en médicos e instituiciones(consultorios, Hospitales , clínicas) .Profesionales a visitar: Neumonólogos-Pediatras.Debe tener una actitud proactiva orientada al logro de resultados y objetivos, capacidad de trabajo individual y en equipo. Excelente manejo de las relaciones interpersonales.Requisitos Matricula vigente Movilidad propia Disponibilidad para viajar. Experiencia previa da al menos dos años en posiciones similaresOfrecemos excelentes condiciones de trabajo.Zona de Trabajo: AMBA', 1, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 14:55:05', '10-04-2026 09:29:07', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 6, 2628, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225539.html', '2026-04-13T07:05:55.108213');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225570, 13510916, 'Asesor Comercial Prendario', 'Mundo Prendario', 'Asesor Comercial Prendario Resumen del Puesto Buscamos un Asesor Comercial Prendario con gran potencial para unirse a nuestro equipo en expansión. El objetivo principal será desarrollar y gestionar una red comercial sólida, asegurando la eficiencia operativa y contribuyendo a la toma de decisiones estratégicas. Responsabilidades Desarrollar y mantener una red de agencias y concesionarios. Gestionar y dar seguimiento a las operaciones comerciales. Elaborar reportes de gestión para apoyar la estrategia comercial. Requisitos Experiencia mínima de 1 año en comercialización de productos financieros o servicios. Conocimiento intermedio del paquete Office y manejo de redes sociales/aplicaciones. Proactividad, excelentes habilidades interpersonales y de trabajo en equipo. Capacidad de organización y resolución de problemas. Marcado perfil comercial. Se valorará poseer movilidad propia. Beneficios Sueldo base competitivo con atractivos esquemas de comisiones. Capacitación continua. Oportunidades de desarrollo y crecimiento profesional. Excelente ambiente de trabajo.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 15:04:38', '10-04-2026 10:11:05', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 6, 23, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13510916_bum_vc47e8489.jpg', NULL, NULL, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225570.html', '2026-04-13T07:05:55.108319');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224430, 13062999, 'ASESOR COMERCIAL - POSADAS', 'Sancor Salud', 'Somos Grupo SanCor Salud, uno de los principales Grupos de Medicina Privada y Grupo Empresario. A través de nuestras diferentes unidades de negocio, brindamos soluciones y desarrollamos productos enfocados en preservar el bienestar de los argentinos. Trabajamos con energía y entusiasmo para ofrecer calidad de servicio a personas y empresas, sin perder de vista nuestros orígenes y valores. En SanCor Salud tenemos una oportunidad para quienes:• Incentiven la cercanía y el buen clima laboral.• Desafíen los procesos y abran camino a formas innovadoras de trabajo.• Se desempeñen con pasión, profesionalismo y compromiso.• Disfruten trabajar en equipos colaborativos y multidisciplinarios¡Sumate vos también y #DesafiateConNosotros! #TuMejorVersión #EstoyDondeQuieroEstar Estamos buscando ASESOR COMERCIAL para el equipo de Posadas/Misiones (Desarrollo de Zona).Quien ocupe dicha posición deberá: Planificar, ejecutar y concretar la comercialización de los productos ofrecidos. Realizar desarrollo de Zona. Captar a potenciales clientes, realizar el ofrecimiento de los productos de la empresa y concretar la venta. Desarrollar estrategias para la captación de nuevos Asociados. Cumplimentar en tiempo y en forma con los objetivos de venta definidos. Consolidación de la cartera de potenciales asociados.Si tenes una fuerte orientación a los resultados, contas con excelente proactividad para la venta de intangibles, te perfilas hacia la innovación en nuevos métodos de trabajo y te interesan los desafíos ES TU OPORTUNIDAD!Queremos que aquí seas #TuMejorVersión. Requisitos: Experiencia en venta de intangibles (salud, seguros, ART, etc.) Predisposición para la venta en terreno, telefónica y por redes sociales. Beneficios • Ser parte de uno de los principales Grupos de Medicina Privada y Grupo Empresario a escala nacional que, a través de sus diferentes unidades de negocio, brinda soluciones y desarrolla productos enfocados en proteger el bienestar de los argentinos.• Ser protagonista de tu desarrollo profesional. ¡A través de nuestra propia Universidad Corporativa acompañamos tu formación!• Trabajar con pasión, compromiso, cercanía e innovación sin perder de vista nuestros orígenes, para ofrecer servicios de excelencia.En SanCor Salud #EstoyDondeQuieroEstar', 0, 'Posadas, Misiones', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 19:51:27', '08-04-2026 19:51:27', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13062999_bum_vaf7bbda6.jpg', 1, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, 'https://certificaciones.greatplacetowork.com.ar/sancor-salud', 'https://www.bumeran.com.ar/empleos/1118224430.html', '2026-04-13T07:05:55.108478');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118220137, 571220, 'Asesor Comercial de Ventas', 'Multigol.', 'En Multigol, somos la plataforma que transforma el ahorro en realidades tangibles. Nos dedicamos a facilitar el acceso a autos, motos e importantes sumas de dinero en efectivo a través de un sistema de cuotas accesibles y capitalización mensual.Nuestra misión es clara: brindamos una alternativa inteligente para que nuestros clientes vean crecer sus ahorros mes a mes mediante intereses competitivos y la posibilidad de cumplir sus sueños a través de los sorteos mensuales de la Lotería de la Ciudad de Buenos Aires (LotBA). Con una red de agencias en expansión, somos el puente entre el esfuerzo de la gente y sus grandes objetivos.¿Qué buscamos?En pleno proceso de crecimiento, buscamos talentos con ADN comercial que quieran ser protagonistas de esta expansión. Si te apasionan las ventas y buscás un entorno dinámico, ¡te estamos buscando! ¡Sumate a la Fuerza de Ventas Líder: Convertite en Productor Asesor en Multigol!En Multigol, transformamos el ahorro en realidades tangibles a través de nuestros Sistemas de Capitalización. Buscamos perfiles comerciales con ambición que quieran profesionalizarse y desarrollar una carrera independiente con el respaldo de una empresa líder.¿Qué te ofrecemos? Profesionalización: Gestión de tu matrícula como Productor Asesor Independiente. Formación Integral: Capacitación teórica y práctica constante. Ingresos Superiores: Excelentes comisiones por objetivos. Herramientas Tecnológicas: Acceso a sistema CRM de última generación para la gestión de datos. Crecimiento Real: Posibilidad de desarrollo y ascenso comprobable dentro de la estructura. Entorno Dinámico: Excelente clima laboral e incorporación inmediata. Requisitos: Edad: De 18 a 35 años. Perfil Proactivo: Personas con actitud positiva y marcado perfil comercial. Habilidades Blandas: Gran capacidad de comunicación, escucha activa y empatía. Autogestión: Responsabilidad, autonomía y orientación a resultados. Disponibilidad: Full-time. Educación: Secundario completo (excluyente). Experiencia: Valoraremos contar con al menos 1 año en ventas (preferentemente de intangibles), aunque no es excluyente. Beneficios ¿Por qué elegirnos? Excelentes ingresos y premios por objetivos. Capacitación continua y matrícula profesional bonificada. Clima laboral inmejorable en un entorno de sano crecimiento. Oportunidades reales de ascenso dentro de la organización.', 0, 'Mendoza, Mendoza', 'Presencial', 'Full-time', '06-04-2026', '06-04-2026 16:11:34', '06-04-2026 16:11:34', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 4, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_571220_bum_v16f3754e.jpg', 0, 0, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118220137.html', '2026-04-13T07:05:55.108644');
