opios.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '06-04-2026', '06-04-2026 18:21:40', '06-04-2026 18:21:40', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13508238_bum_v8038f4d.jpg', NULL, NULL, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118220476.html', '2026-04-13T07:05:55.108777');
