opios.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '06-04-2026', '06-04-2026 17:54:46', '08-04-2026 14:36:20', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13508238_bum_v8038f4d.jpg', NULL, NULL, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118220407.html', '2026-04-13T07:05:55.108893');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227128, 10222469, 'Asesor/a Comercial de Inversiones & Patrimonios', 'Perfil Humano', 'Para empresa líder en asesoramiento financiero, buscamos incorporar un profesional con perfil comercial y visión estratégica para desarrollar y gestionar relaciones con clientes empresariales y patrimoniales. Preferentemente con formación universitaria en Administración, Economía, Contabilidad o afines. Experiencia comprobable en desarrollo comercial y gestión de clientes, con foco en asesoramiento financiero y/o mercado de capitales.Misión del puesto: Desarrollar y consolidar relaciones comerciales de largo plazo, identificando oportunidades de negocio y brindando asesoramiento financiero integral, contribuyendo al crecimiento sostenido de la compañía.Principales desafíos del puesto: Detectar estrategias de captación y desarrollo de clientes. Desarrollar nuevas oportunidades comerciales. Gestionar cartera de clientes corporativos y patrimoniales. Brindar asesoramiento en inversiones y planificación financiera. Trabajar en conjunto con equipos de Wealth Management. Asegurar altos estándares de servicio, confidencialidad y ética profesional.Valoraremos: Perfil comercial con fuerte orientación a resultados. Contar con conocimientos en Mercado de Capitales y cartera de clientes. Habilidades de negociación y venta consultiva. Excelente comunicación. Trabajo en equipo Ética profesional y confidencialidad Proactividad y autonomía.', 0, 'Mendoza, Mendoza', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 14:54:56', '10-04-2026 14:54:56', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 6, 2628, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_10222469_bum_vaaa45d63.jpg', 0, 0, NULL, 40, 'Destacados', 'bumeran', 'destacado', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227128.html', '2026-04-13T07:05:55.109015');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224738, 10119023, 'Asesores/as Comerciales Lobos', 'Adecco - Región NOA, Cuyo, Patagonia', 'BUSCAMOS TALENTOS,¡EN ADECCO TE ESTAMOS BUSCANDO!Estamos buscando Ejecutivo/a de Ventas Territoriales para incorporarse al equipo de Adecco prestando servicios a nuestro cliente, Plataforma líder de servicios E-Commerce, en nuestro país.¿QUÉ DESAFÍOS TE ESPERAN? Detectar oportunidades de negocio de adquisición para soluciones de cobro presenciales (QR y point). Incorporar nuevos comercios y gestionar una cartera de clientes propia. Asistir y capacitar a los nuevos clientes de la cartera en la puesta en marcha de sus operaciones, tendrá a cargo un territorio asignado. Gestionar vía telefónica y/o reuniones online base de potenciales clientes. Complementar la gestión online con acciones comerciales presenciales en zona asignada. Planificar la agenda propia de despliegue territorial para optimizar y aumentar ventas. Análisis de principales métricas del negocio y presentar informes continuos para visibilidad de desempeño e identificar alertas y oportunidades.¿QUÉ VALORAMOS DE TU PERFIL? Experiencia en áreas comerciales y análisis de datos desarrollada en posición similar (excluyente). Secundario completo con analítico en mano (excluyente). Deseable estar cursando o ser graduado/a de carreras económicas, marketing, comercialización, Ingeniería Industrial. Actitud comercial. Comunicación y persuasión. Orientación a resultados y calidad. Autonomía.¿QUE TE OFRECEMOS? Lugar de trabajo: Trabajo en campo zona Beccar Modalidad: Presencial. Jornada laboral: Lunes a viernes de 9 a 1 8hs. Ofrecemos: Sueldo + comisiones por venta + viáticos + PC+ herramientas de trabajo.Somos Adecco Argentina una compañía con más de 3 0 años de experiencia que conecta empresas con talentos, brindando soluciones integrales de Recursos Humanos y buscamos talentos, ¡COMO VOS! Nuestro compromiso es la #diversidad e #igualdad de oportunidades, somos una empresa inclusiva. Cuando sos parte de nuestros procesos, solo cuentan tus méritos, logros y capacidades, lo hacemos pensando en vos como persona. Participar de nuestros procesos de selección no tiene ningún costo para vos candidato/a, trabajar con vos es parte de nuestro compromiso y tarea con la comunidad. Postúlate y participa en una oferta de empleo nuestra. El empleador sólo podrá solicitarle la información estrictamente necesaria para el desempeño en el trabajo que se ofrece. Ciudad de Buenos Aires: ley de búsqueda laboral equitativa - Ley 6 4 7', 0, 'Lobos, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 15:07:06', '10-04-2026 09:51:04', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/1/0/1/1/9/0/2/3/logoMainPic_10119023_bum_vad1d6456.jpg', 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224738.html', '2026-04-13T07:05:55.109184');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179278, 565223, 'Recepcionista Administrativa - Sector Seguros', 'Lauro Asesores', 'Recepcionista Administrativa - Sector Seguros Resumen del Puesto Estamos en la búsqueda de una Recepcionista Administrativa proactiva y organizada, con experiencia específica en el ámbito de brokers de seguros. El rol principal será la gestión y carga de siniestros en las plataformas correspondientes, asegurando la eficiencia y precisión en los procesos. Responsabilidades Recepción y atención de consultas generales. Gestión de la agenda y coordinación de reuniones. Carga y seguimiento de siniestros en las plataformas del sector seguros. Colaboración en tareas administrativas generales del área. Mantenimiento de la documentación y archivos organizados. Requisitos Experiencia previa comprobable como recepcionista administrativa. Conocimiento y experiencia en el sector de seguros, específicamente en la carga de siniestros. Manejo de herramientas ofimáticas (procesador de texto, planilla de cálculo). Habilidades de organización, atención al detalle y proactividad. Capacidad para trabajar de forma autónoma y en equipo. Excelentes habilidades de comunicación.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 15:13:30', '09-04-2026 15:32:52', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 26, 2380, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179278.html', '2026-04-13T07:05:55.109316');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225797, 13051395, 'Asesor de Ventas – Región CÓRDOBA', 'Saiba Recursos Humanos', 'Nuestro cliente, una empresa multinacional líder en soluciones de automatización industrial, incorporará:Asesor de Ventas – Región CÓRDOBABuscamos profesionales de las Carreras de Ingeniería en Mecatrónica, Electrónica, Industrial, Automatización y/o afines que cuenten con experiencia previa en roles similares, tengan dominio del idioma inglés, pleno manejo de herramientas digitales (CRM, Excel, PowerPoint) y conocimientos generales de PLC. Las principales responsabilidades que tendrá asignadas son: Lograr la metas de venta anual de la región asignada, desarrollando estratégicamente clientes y distribuidores. Potenciar el mercado de Córdoba, generando oportunidades, coordinando con Soporte Técnico y Marketing, posicionando a la compañía como socio estratégico de los clientes. Ejecutar el plan de negocios, gestionar ventas estratégicas, planificar actividades en CRM, detectar oportunidades técnicas, realizar visitas, dar apoyo a distribuidores y coordinar la administración comercial de las cuentas a cargo.Valoramos candidatos con habilidades de venta consultiva y estratégica, capacidad analítica y de planificación, orientados a resultados, que sientan pasión por el trabajo en equipo y sean asertivos y empáticos al momento de comunicarse y generar vínculos de largo plazo.La modalidad de trabajo es híbrida.', 0, 'Córdoba, Córdoba', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 16:52:01', '09-04-2026 16:52:01', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 6, 23, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/1/3/0/5/1/3/9/5/logoMainPic_13051395_bum_vb3b6d5e1.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225797.html', '2026-04-13T07:05:55.109472');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223107, 571220, 'Asesor Comercial de Ventas - Salta', 'Multigol.', 'En Multigol, somos la plataforma que transforma el ahorro en realidades tangibles. Nos dedicamos a facilitar el acceso a autos, motos e importantes sumas de dinero en efectivo a través de un sistema de cuotas accesibles y capitalización mensual.Nuestra misión es clara: brindamos una alternativa inteligente para que nuestros clientes vean crecer sus ahorros mes a mes mediante intereses competitivos y la posibilidad de cumplir sus sueños a través de los sorteos mensuales de la Lotería de la Ciudad de Buenos Aires (LotBA). Con una red de agencias en expansión, somos el puente entre el esfuerzo de la gente y sus grandes objetivos.¿Qué buscamos?En pleno proceso de crecimiento, buscamos talentos con ADN comercial que quieran ser protagonistas de esta expansión. Si te apasionan las ventas y buscás un entorno dinámico, ¡te estamos buscando! ¡Sumate a la Fuerza de Ventas Líder: Convertite en Productor Asesor en Multigol!En Multigol, transformamos el ahorro en realidades tangibles a través de nuestros Sistemas de Capitalización. Buscamos perfiles comerciales con ambición que quieran profesionalizarse y desarrollar una carrera independiente con el respaldo de una empresa líder.¿Qué te ofrecemos? Profesionalización: Gestión de tu matrícula como Productor Asesor Independiente. Formación Integral: Capacitación teórica y práctica constante. Ingresos Superiores: Excelentes comisiones por objetivos. Herramientas Tecnológicas: Acceso a sistema CRM de última generación para la gestión de datos. Crecimiento Real: Posibilidad de desarrollo y ascenso comprobable dentro de la estructura. Entorno Dinámico: Excelente clima laboral e incorporación inmediata. Requisitos: Edad: De 18 a 35 años. Perfil Proactivo: Personas con actitud positiva y marcado perfil comercial. Habilidades Blandas: Gran capacidad de comunicación, escucha activa y empatía. Autogestión: Responsabilidad, autonomía y orientación a resultados. Disponibilidad: Full-time. Educación: Secundario completo (excluyente). Experiencia: Valoraremos contar con al menos 1 año en ventas (preferentemente de intangibles), aunque no es excluyente. Beneficios ¿Por qué elegirnos? Excelentes ingresos y premios por objetivos. Capacitación continua y matrícula profesional bonificada. Clima laboral inmejorable en un entorno de sano crecimiento. Oportunidades reales de ascenso dentro de la organización.', 0, 'Salta, Salta', 'Híbrido', 'Full-time', '08-04-2026', '08-04-2026 12:07:08', '08-04-2026 12:07:08', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 4, 1, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_571220_bum_v16f3754e.jpg', 0, 0, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223107.html', '2026-04-13T07:05:55.109628');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225984, NULL, 'Asesor Comercial – Marca de Deportes de Combate y Artes Marciales (Ventas + Asesoramiento)', 'Confidencial', 'Estamos buscando sumar a una persona para el equipo comercial de una marca de equipamiento para deportes de combate y artes marciales (boxeo, kickboxing, MMA, muay thai, taekwondo, etc.).El puesto es para llevar la venta y el asesoramiento online con clientes que preguntan todos los días y necesitan respuestas claras, rápidas y con criterio.Vas a trabajar con estos canales: 📲 WhatsApp | 📷 Instagram | 📘 Facebook | 🛒 Mercado Libre | 🧩 Kommo (CRM) Este rol es para a quien tiene actitud comercial, sabe conversar con clientes y se compromete con el seguimiento.TAREAS PRINCIPALES:✅ Responder consultas en todos los canales online ✅ Asesorar según lo que el cliente necesita (uso, nivel, objetivo) ✅ Recomendar productos con criterio y buena comunicación ✅ Hacer seguimiento y ordenar conversaciones en CRM. ✅ Cerrar ventas y empujar la compra hasta concretarla ✅ Identificar oportunidades (profes, gimnasios, mayoristas)PERFIL IDEAL🔹 Edad: 20 a 30 años (excluyente) 🔹 Perfil: comercial, activo, resolutivo y con hambre de mejorar 🔹 Comunicación: buena onda, claro, sin vueltas, con presencia 🔹 Orden: seguimiento y responsabilidad con las conversaciones Suma muchísimo: ⭐ Experiencia en ventas (online / atención comercial / e-commerce / ML / WhatsApp) ⭐ Conocimiento o vínculo con deportes de combate o artes marciales LO QUE OFRECEMOS💰 Sueldo base + comisiones por ventas 📍 Presencial en Quilmes 👥 Equipo joven y dinámico 📈 Posibilidad real de crecimientoPOSTULACIÓN📩 Enviá tu CV a: LAUTARO.UNLIMITED๑GMAIL.COM 📧 📌LAUTARO.UNLIMITED#GMAIL.COM 📌 Asunto: Asesor Comercial✅ CV actualizado ✅ Si tenés experiencia, si querés contarnos por qué te gustaría sumarte al equipo, ideas o lo que creas que sume… ¡Los vamos a estar leyendo!', 1, 'Quilmes, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 17:55:06', '10-04-2026 11:10:10', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225984.html', '2026-04-13T07:05:55.109832');
