INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224986, 13037589, 'ASISTENTE EXPERIMENTADO DE IMPUESTOS', 'Consultora', 'PARA IMPORTANTE ESTUDIO DE AUDITORIA, IMPUESTOS Y CONTABILIDAD ubicado en PUERTO MADEROBUSCAMOS ASISTENTE EXPERIMENTADO DE IMPUESTOSContador ó estudiante avanzado, preferentemente con Impuestos II cursado y aprobado con Experiencia mínima 1 ó 2 años en el puesto (excluyente) Conocimientos avanzados en EXCEL.Perfil analítico, autónomo, con responsabilidad, compromiso., capacidad para trabajar en equipo y bajo presión.Objetivo del puesto: Liquidación de impuestos indirectos y directos (este último no excluyente). Armado y seguimiento de vencimientos.Tareas: Liquidación de Impuestos indirectos y directos – Incluye liquidación, carga en aplicativo, armado de archivos para importación de datos, generación de presentación y pago VEP, seguimiento. Liquidación de Agentes de recaudación Nacional y Provincial – incluye determinación, validación, armado de DDJJ, generación de presentación y pago VEP, seguimiento. Armado de calendario y envio a clientes Conciliaciones cuentas impositivas Tramites generales antes los diferentes fiscos provinciales y el fisco nacional Tramitación de Certificados de exclusión. Seguimiento de vencimientos.Forma de contratación: Contrato por tiempo indeterminado con el Estudio.Horario: de trabajo: de 9hs a 18hsAlmuerzo: La empresa tiene comedor con disponibilidad de microondas, heladera, horno eléctrico. También pueden tener ese espacio para almorzar. Estáa disponible y es de libre acceso en cualquier horario de la jornada.Lugar de trabajo: Esquema Hibrido (2 días presencial en la oficina de Puerto Madero - CABA y 3 home)Beneficios: Prepaga Galeno Azul – SMG 20 Vacaciones 10 días hábiles Bonificación Sport Club (60%) 20% descuento en Universidad de Belgrano Día de cumpleaños OFF Tiendas Amigas (descuentos y promociones en tiendas) Beneficio Mercado Pago Billetera Virtual', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 11:48:45', '10-04-2026 13:01:27', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 1, 90, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13037589_bum_va27abd77.jpg', 0, 0, 4.0, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224986.html', '2026-04-13T07:05:55.111047');
