INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226689, 1282780, 'Asistente administrativa generalista Moreno', 'Adecco - Permanent Talent', 'BUSCAMOS TALENTOS, ¡EN ADECCO TE ESTAMOS BUSCANDO!Si te interesa trabajar Asistente administrativa generalista en el equipo de IMPORTANTE EMPRESA ¡desafíate a vos mismo y crea tu futuro!¿QUÉ DESAFÍOS TE ESPERAN? Administración General y Soporte Administrativo Completar y actualizar horarios de ingreso y egreso del personal en planillas de RRHH. Control de horas del personal productivo. Mantener actualizados los legajos del personal. Organización y archivo de documentación física y digital. Elaboración de fotocopias y documentación administrativa general. Actualización de planillas administrativas (pagos, cobros, ingreso de facturas). Control y gestión de correspondencia, envíos y recepción de paquetes. Carga de retenciones de ganancias/IIBB en los portales de ARCA/ARBA. Secretaría y Atención General Recepción de visitas y apoyo en atención institucional. Preparación y organización de salas de reuniones. Coordinación logística básica (taxis, hoteles, vuelos, alquiler de vehículos, etc.). Apoyo ocasional en la atención a visitas. Comunicación interna mediante murales y correos generales. Soporte Operativo Transversal Control de la Carpeta de Procedimientos (numeración, actualización y comunicación). Carga de legajos de recepciones, despachos y importaciones. Asistencia en rutinas administrativas diarias. Cotización y compras simples de insumos básicos. Organización y control del stock de insumos de oficina. Recepción de entregas y control básico de materiales. Control de llaves, accesos y materiales. Entrega de EPP y otros insumos al equipo. Gestión de compras menores relacionadas con eventos internos. Coordinación Administrativa y Cumplimiento Coordinación y apoyo durante inspecciones laborales o municipales. Realización de trámites administrativos ante bancos, municipalidad u organismos oficiales.¿QUÉ VALORAMOS DE TU PERFIL? Estudiante de carreras de administracion o contaduria (Excluyente) Experiencia labora en el area de administracion 2/3 años (Excluyente) Conocimientos básicos de informática y herramientas digitales. Perfil organizado, proactivo y orientado al servicio. Capacidad para gestionar múltiples tareas simultáneamente. Buenas habilidades de comunicación interpersonal. Actitud colaborativa y disposición para trabajar con diferentes áreas. Movilidad propia (deseable)¿QUE TE OFRECEMOS? Horario: lunes a viernes de 8 a 17hs o 9 a 18hs Lugar de trabajo: Moreno, Cuartel V. Modalidad: presencial Contratacion a tiempo indeterminado en directo con la empresa Prepaga para colaborador/a + grupo familiar. Bono anual sujeto a cumplimiento de objetivos Regalos corporativosSomos Adecco Argentina una compañía con más de 30 años de experiencia que conecta empresas con talentos, brindando soluciones integrales de Recursos Humanos y buscamos talentos, ¡COMO VOS! Nuestro compromiso, es la #diversidad e #igualdad de oportunidades somos una empresa inclusiva. Cuando sos parte de nuestros procesos, solo cuentan tus méritos, logros y capacidades, lo hacemos pensando en vos como persona. Participar de nuestros procesos de selección no tiene ningún costo para vos candidato/a, trabajar con vos es parte de nuestro compromiso y tarea con la comunidad. Postulate y participa en una oferta de empleo nuestra. El empleador sólo podrá solicitarle la información estrictamente necesaria para el desempeño en el trabajo que se ofrece. Ciudad de Buenos Aires: ley de búsqueda laboral equitativa - Ley 6471', 0, 'Moreno, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 11:49:57', '10-04-2026 12:00:00', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/0/1/2/8/2/7/8/0/logoMainPic_1282780_bum_vf37880d6.jpg', 0, 0, 3.73, 70, 'Simples', 'bumeran', 'simple', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226689.html', '2026-04-13T07:05:55.111337');
