res', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 16:32:02', '09-04-2026 16:32:02', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, NULL, NULL, NULL, NULL, 70, 'Avisos Classic', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179294.html', '2026-04-13T07:05:55.111645');
