ncial', 'Full-time', '10-04-2026', '10-04-2026 14:31:27', '10-04-2026 14:31:27', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 25, 2571, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_10151272_bum_va9b5c600.jpg', 0, 0, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227077.html', '2026-04-13T07:05:55.111912');
