INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118221424, 466770, 'Auditor/a de calidad', 'BAYTON', 'Nos encontramos en la búsqueda de un/a Auditor/a de Calidad para incorporarse a un equipo en crecimiento, con foco en el aseguramiento (QA) y control de calidad (QC) dentro del rubro salud. La posición se integra a un equipo especializado que lidera procesos de auditoría y mejora continua, garantizando el cumplimiento de estándares en la gestión de stock, almacenamiento y circuitos operativos.Principales responsabilidades: Auditar la correcta ejecución de procesos operativos vinculados a stock y mercadería. Controlar circuitos de almacenamiento, incluyendo productos de cadena de frío, psicotrópicos y artículos de alto costo. Realizaranálisis de stock, cruces de datos y detección de desvíos. Participar activamente en la propuesta e implementación de mejoras en procesos y circuitos. Coordinar y cumplir cronogramas de auditoría en distintas sucursales, incluyendo visitas a otras localidades.Requisitos: Experiencia mínima de 2 años en gestión de calidad, auditoría o análisis de procesos (preferente). Perfil analítico, con orientación a resultados y mejora continua. Capacidad operativa y mirada integral del negocio. Organización, estructura y apego a procedimientos. Flexibilidad y adaptación a entornos dinámicos. Carnet de conducir vigente (excluyente). Condiciones: Jornada laboral de lunes a viernes de 8 a 17 hs. Disponibilidad para viajes en la provincia. Esquema flexible ante eventualidades operativas, con compensaciones. Excelente oportunidad de desarrollo profesional, con proyección.Buscamos personas comprometidas, con iniciativa y ganas de formar parte de un equipo que impulsa mejoras y profesionalización en los procesos.', 0, 'Comodoro Rivadavia, Chubut', 'Híbrido', 'Full-time', '07-04-2026', '07-04-2026 13:02:06', '07-04-2026 13:02:06', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 23, 2692, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_466770_bum_v7cd0e054.jpg', 1, 0, 3.9, 70, 'Simples', 'bumeran', 'simple', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221424.html', '2026-04-13T07:05:55.112844');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118216060, 1478000, '1329 CC | MÉDICO AUDITOR SR. | ÁREA AMBULATORIA | SAN MARTÍN, BS. AS. | L A V 8 A 14 HS', 'CONA CONSULTORES EN RRHH', 'Nos encontramos en la búsqueda de un Médico/a Auditor/a Senior. Orientamos nuestra búsqueda a perfiles que cuenten amplia trayectoria en auditoría médica, criterio técnico y capacidad de gestión.Responsabilidades: Evaluación técnico-médica de prestaciones ambulatorias. Auditoría de órdenes médicas, prácticas diagnósticas y tratamientos, conforme a normativas y criterios de cobertura. Control técnico de facturación de prestaciones, identificando débitos, inconsistencias y desvíos Autorización y/o rechazo fundado de prácticas médicas según criterios clínicos y administrativos. Análisis de sobreutilización, subutilización y desvíos en la indicación de prestaciones Interacción técnica con prestadores para auditorías concurrentes y retrospectivas Elaboración de informes técnicos, dictámenes y reportes de gestión Participación en la revisión y actualización de circuitos y procesos de auditoría Aplicación de indicadores de gestión, calidad y costos en auditoría médica. Asesoramiento técnico a áreas internas en relación con cobertura, prestaciones y criterios médicosRequisitos: Título de Médico con matrícula habilitante Experiencia mínima de 10 años en auditoría médica ambulatoria Conocimiento avanzado de nomencladores nacionales (PMO, Nomenclador Nacional, etc.) Manejo de normativas regulatorias del sistema de salud Experiencia en validación de prestaciones y control de facturación médica Dominio de herramientas informáticas y sistemas de gestión sanitariaCondiciones de contratación: Contratación directa y permanente con el Sanatorio Excelente Remuneración y Beneficios competitivos con el mercado Agradable clima laboral y Reales posibilidades de desarrollo profesional Jornada laboral: lunes a viernes Horario: 08:00 a 14:00 hs Zona de trabajo: San Martin (GBA)CUIDATE DE LOS AVISOS LABORALES FALSOSEn CONA siempre postulás por plataformas de empleo directas, nunca a través de personas individuales. Nunca te pediremos enviar foto del DNI ni documentación personal.Búsqueda laboral equitativa: el empleador solo podrá solicitar la información estrictamente necesaria para el desempeño del trabajo ofrecido. Ley 6471-21 GCBA.', 0, 'San Martin, Buenos Aires', 'Presencial', 'Full-time', '01-04-2026', '01-04-2026 08:51:01', '08-04-2026 08:52:10', '2026-04-01', NULL, NULL, '2026-04-01T00:00:00-03:00', NULL, NULL, 1, 0, 23, 2650, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_1478000_bum_vcc157e48.jpg', 0, 0, 3.13, 70, 'Simples', 'bumeran', 'simple', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118216060.html', '2026-04-13T07:05:55.112991');
