🚀', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 18:03:09', '10-04-2026 13:52:29', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 1, 58, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_669026_bum_v5f63e078.jpg', 0, 0, NULL, 70, 'Avisos Classic', 'zonajobs', 'zonajobs', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179313.html', '2026-04-13T07:05:55.113130');
