INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2176116, NULL, 'Ejecutivo/a Comercial de Seguros Automotores', 'Confidencial', '¿Te apasiona el mundo de los seguros y los desafíos comerciales? ¡Te estamos buscando! 🎯Importante Broker de seguros generales busca un ejecutivo de cuentas para su equipo comercialno solo vendemos pólizas, brindamos tranquilidad a nuestros clientes cuando más lo necesitan.Estamos creciendo y buscamos un Ejecutivo Comercial de Seguros Automotores con "chispa", empatía y mucha agilidad digital.¿Qué harás en tu día a día? Serás el asesor de confianza para conductores que buscan la mejor protección. Gestionarás prospectos desde la primera consulta hasta la emisión de la póliza. Utilizarás herramientas de última generación (CRM y multicotizadores) para ser el más rápido del mercado. Fidelizarás tu cartera: porque un cliente bien cuidado es un cliente para siempre.¿Qué buscamos en ti? ADN Comercial: Tienes resiliencia y te motiva alcanzar (y superar) objetivos. Expertise Técnico: Conoces la diferencia entre un "Terceros Completo" y un "Todo Riesgo" como la palma de tu mano. Agilidad Digital: Te llevas de maravilla con el CRM, Excel y WhatsApp Business. Empatía: Sabes escuchar y comunicar con claridad, incluso en momentos de estrés.¿Qué ofrecemos? ✨ Un ambiente de trabajo dinámico y colaborativo. 📈 Basico + Esquema de comisiones 🎓 Capacitación 🏠 Home Office, 4x1 y 2 viermes flex por mes¿Sientes que este puesto tiene tu nombre?¡Queremos conocerte!', 1, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '26-02-2026', '26-02-2026 13:26:05', '09-04-2026 15:13:48', '2026-02-26', NULL, NULL, '2026-02-26T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, NULL, NULL, NULL, NULL, 70, 'Avisos Classic', 'zonajobs', 'zonajobs', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2176116.html', '2026-04-13T07:05:55.113524');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224788, NULL, 'Supervisor de Posventa (automotriz)', 'Confidencial', 'Nos encontramos en la búsqueda de un/a Supervisor/a de Posventa para liderar integralmente la operación de servicio, repuestos y taller, con foco en resultados, calidad y experiencia del cliente.Principales responsabilidades: Liderar la operación completa de posventa (taller, repuestos y atención). Definir, implementar y controlar indicadores de gestión (facturación, eficiencia, productividad, NPS, ticket promedio). Asegurar la rentabilidad del negocio de posventa. Coordinar y desarrollar a los líderes de cada sector (jefe de taller, repuestos, asesores de servicio). Detectar oportunidades de mejora y optimizar procesos. Garantizar estándares de marca y auditorías (calidad, PGI, 5S). Gestionar la experiencia del cliente y resolución de conflictos críticos. Planificar la operación en función de la demanda. Requisitos: Experiencia en posiciones de liderazgo en posventa automotriz, no menor a 3 años. Visión integral del negocio: técnica y comercial. Experiencia en gestión de equipos y mandos medios. Fuerte orientación a resultados y KPIs. Capacidad analítica y toma de decisiones. Excelente manejo de relaciones interpersonales.Valoramos: Experiencia en concesionarias oficiales. Conocimiento en estándares de marca. Formación en gestión o liderazgo.', 1, 'San Fernando del Valle de Catamarca, Catamarca', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 10:57:21', '09-04-2026 10:57:21', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 16, 70, 1, NULL, NULL, NULL, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224788.html', '2026-04-13T07:05:55.113641');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224539, 10065994, 'Asistente Exp. contable', 'Casin y Asociados S.R.L.', 'Casin es una organización destinada para y hacia los clientes. Analizamos y ayudamos a cada uno de nuestros clientes respaldándonos en un amplio conocimiento en Audit, Outsourcing, Payroll, Consulting, Loan Staff y Tax.Más de 100 profesionales entrenados combinan habilidades técnicas y de negocios para lograr un asesoramiento de excelencia, que mejoran día a día el desempeño y negocio de empresas de capitales multinacionales, regionales y nacionales.Actualmente, contamos con oficinas en Argentina, Brasil, Estados Unidos, España, Panamá y Perú, logrando de esta forma generar sinergia dentro de Iberoamérica. Al mismo tiempo, estamos proyectando el desembarco en otros países de Latinoamérica.Priorizamos un modelo de negocio de triple impacto y servicios que tienen como principales ejes la personalización, confianza, el profesionalismo y un trabajo en equipo de alta calidad, combinado con una fluída comunicación en la operatoria diaria, que permite un mayor entendimiento del negocio de nuestros clientes.Nuestro compromiso con el Triple Impacto está respaldado en informes técnicos y acciones concretas; trabajamos día a día en mejorar nuestros procesos, estructura y acciones externas para poder lograr un impacto social y medioambiental positivo, sin descuidar y priorizando producir valor económico sostenible. ¡Queremos que formes parte de nuestro equipo!En Casin nos encontramos en búsqueda de una persona que se encuentre estudiando la carrera de Contador/Admnistración y con experiencia en puestos similares para formar parte de una importante empresa. ¿Qué responsabilidades tendrás en la posición? Revisión registración contable realizada y retenciones calculadas. Confección transferencias en plataforma bancaria. Confección DDJJ SICORE y SIRE. Análisis y conciliación de cuentas (y armado de asientos en caso de corresponder) de las cuentas de bancos, proveedores, deudores por venta, TJ de crédito, Gs. Caja, Devengamientos y diferencias de cambio. Armado información para liquidaciones impositivas. Armado libro inventario y balances. Atención a consultas de auditores.¿Qué competencias consideramos necesarias para la posición? Flexibilidad. Compromiso con el cliente y las tareas. Organización del tiempo y prioridades. Capacidad para trabajar en equipo. Empatía. Proactividad¿Cuáles son las condiciones de contratación que te ofrecemos? Jornada laboral de lunes a viernes de 9 a 18Hs. Modalidad de trabajo: Híbrida Lugar de trabajo: Microcentro - CABA Contrato por tiempo indeterminado. Requisitos: Secundario contable. Estudiante promediando la carrera de Contador/administrador y tener aprobadas las materias contables. Excel Intermedio. Entre 1 y 2 años de experiencia en puestos similares. Se valorará que sepa usar Tango o algún otro sistema de gestión. Beneficios Medicina privada Día de cumpleaños libre', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '08-04-2026', '08-04-2026 21:10:34', '08-04-2026 21:10:34', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 1, 58, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/1/0/0/6/5/9/9/4/logoMainPic_10065994.jpg', 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224539.html', '2026-04-13T07:05:55.113819');
