INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226025, 10107503, 'Operarios de logística Avellaneda - Eventual', 'Drogueria del Sud S.A', 'Somos la distribuidora integral a farmacias líder en Argentina. Nuestro compromiso indiscutido con los más de 300 laboratorios y 8.000 farmacias que nos acompañan todos los días se evidencia a lo largo de nuestros 70 años de historia.La calidad es nuestra meta, y para nosotros esto significa ofrecer más y mejores soluciones a nuestros clientes y proveedores. Estamos convencidos de que el camino para lograr este objetivo es la inversión constante en innovación tecnológica y de gestión. Esta convicción nos permite garantizar óptimas condiciones de almacenamiento y transporte, y un manejo confiable de trazabilidad de medicamentos que así lo requieren.Desde 1950 somos respaldo y aval de seguridad para nuestros proveedores, clientes y pacientes, sobre todos los productos que distribuimos y comercializamos.Durante nuestro largo camino confiamos en el vínculo cercano y personal con nuestros clientes, socios y colaboradores. La pasión por lo que hacemos, el compromiso, y la ética y profesionalismo de trabajo son nuestros pilares. Combinar siempre las mejores tecnologías y el compromiso de nuestra gente es nuestro diferencial y lo que nos llevó a obtener grandes resultados. Nos encontramos en la búsqueda de operarios depósito y producción para nuestro Centro de Distribución de Avellaneda, Provincia de Buenos Aires.Las tareas a desarrollar serán:· Almacenamiento de la mercadería ingresante en el depósito· Preparar pedidos en la línea de producción· Reponer materiales en góndolas· Embalar y empacar los pedidos terminados· Realizar el control y seguimiento de stock Requisitos: Los interesados deberán poseer el secundario completo y disponibilidad horaria full time. Movilidad propia.Será para cubrir una posición eventual. Beneficios Corporativo', 0, 'Avellaneda, Buenos Aires', 'Presencial', 'Temporario', '09-04-2026', '09-04-2026 18:10:01', '09-04-2026 18:10:01', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 16, 32, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_10107503_bum_vbbda93ba.jpg', 1, 0, 3.2, 40, 'Destacados', 'bumeran', 'destacado', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226025.html', '2026-04-13T07:05:55.114535');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225712, 2612300, 'DevOps (AWS) - Híbrido - 1818', 'Aliantec', '¿Qué hace la compañía?Es una empresa de tecnología que desarrolla soluciones de gestión empresarial en la nube (ERP), orientadas a PyMEs y emprendedores de Latinoamérica.Su plataforma permite centralizar la operación del negocio en un único sistema, facilitando la gestión de procesos clave como facturación electrónica, control de stock en tiempo real, administración de precios, compras y ventas. Además, ofrece integración con los principales ecommerce y marketplaces del mercado, promoviendo una operación más conectada, eficiente y escalable. Se trata de una solución accesible desde cualquier dispositivo, diseñada para simplificar la gestión diaria y optimizar la toma de decisiones en empresas en crecimiento.¿Qué necesitás para ser parte del equipo?A nivel personal: Buenas relaciones interpersonales. Trabajo en equipo y en entornos dinámicos. Creatividad, Proactividad y Flexibilidad. Habilidades para resolución de problemas.A nivel técnico: Más de 3 años de experiencia comprobable en posiciones similares de DevOps (con background sólido en Sysadmin). | Excluyente. Manejo de consola AWS: EC2, S3, SNS, SQS, VPC, DNS. | Excluyente Scripting (shell, bash, ps1, yaml, Groovy) Creación, administración y modificación de entornos Linux (Debian, Ubuntu) y Windows Server. | Excluyente Conocimientos en redes. Implementación de Docker | Excluyente Conocimientos en herramientas de observabilidad, Grafana preferentemente. Conocimientos en IaC como Terraform Conocimientos en SQL. Experiencia con al menos 3 de las siguientes tecnologías: IIS, Nginx, MongoDB, Redis, ClickHouse, montaje de discos, Supervisor, Cron, Firewall DNS. Contar con conocimientos en CloudFlare (WAF, Rate Limits), será un plus! Inglés técnico intermedio Ser estudiante o Profesional universitario de las carreras de ingeniería en sistemas, informática, telecomunicaciones o afín.¿Qué vas a hacer? Mantener operativa la plataforma Garantizar la performance y seguridad del sistema. Asegurar la disponibilidad de guardias pasivas o contacto de emergencia Crear entornos segregados Desarrollar una política de backup escalable Creación de planes de disaster recovery Prever posibles cambios presupuestarios de infraestructura¿Cuál es el desafío de la posición?Junto al Cloud Engineer y al equipo de desarrollo, tendrás por delante el desafío de terminar de implementar CI/CD, cultura de automatización y migraciones de sistemas operativos core y entornos en la nube en su totalidad.¿Con quién trabajarás?Trabajarás en conjunto con el referente del área.¿Cuándo y dónde trabajarás?Trabajarás en el horario de 9 a 18 hs, en un esquema híbrido asistiendo dos días a las oficinas ubicadas en Parque Patricios – martes y miércoles – y 3 días de home offices. La posición cuenta con un esquema de Guardias de 2 semanas por mes.¿Qué ofrecen? Relación de dependencia directa con la empresa. Prepaga de primer nivel. Día de cumpleaños libre + regalo especial. Viernes Flex: 1 viernes al mes con media jornada. 21 días de vacaciones. Happy Summer: 2 fines de semana largos libres en verano. Tarjeta prepaga con crédito mensual. Club de beneficios con descuentos exclusivos. Descuentos en Educación IT.¿De qué fases consta el proceso de selección?Tendrás una primera entrevista con nuestra recruiter, Carla Carrizo, para conocer tus experiencias laborales e intereses. Luego, participarás de dos entrevistas con nuestro cliente, conociendo primero al Líder Técnico (Cloud Engineer), y luego una segunda instancia en donde conocerás al CTO-CEO más una persona de HR.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 16:18:07', '09-04-2026 16:18:07', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2625, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2612300_bum_v71b9694.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'tecnologia', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225712.html', '2026-04-13T07:05:55.114763');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179290, 570364, 'DevOps (AWS) - Híbrido - 1818', 'Aliantec', '¿Qué hace la compañía?Es una empresa de tecnología que desarrolla soluciones de gestión empresarial en la nube (ERP), orientadas a PyMEs y emprendedores de Latinoamérica.Su plataforma permite centralizar la operación del negocio en un único sistema, facilitando la gestión de procesos clave como facturación electrónica, control de stock en tiempo real, administración de precios, compras y ventas. Además, ofrece integración con los principales ecommerce y marketplaces del mercado, promoviendo una operación más conectada, eficiente y escalable. Se trata de una solución accesible desde cualquier dispositivo, diseñada para simplificar la gestión diaria y optimizar la toma de decisiones en empresas en crecimiento.¿Qué necesitás para ser parte del equipo?A nivel personal: Buenas relaciones interpersonales. Trabajo en equipo y en entornos dinámicos. Creatividad, Proactividad y Flexibilidad. Habilidades para resolución de problemas.A nivel técnico: Más de 3 años de experiencia comprobable en posiciones similares de DevOps (con background sólido en Sysadmin). | Excluyente. Manejo de consola AWS: EC2, S3, SNS, SQS, VPC, DNS. | Excluyente Scripting (shell, bash, ps1, yaml, Groovy) Creación, administración y modificación de entornos Linux (Debian, Ubuntu) y Windows Server. | Excluyente Conocimientos en redes. Implementación de Docker | Excluyente Conocimientos en herramientas de observabilidad, Grafana preferentemente. Conocimientos en IaC como Terraform Conocimientos en SQL. Experiencia con al menos 3 de las siguientes tecnologías: IIS, Nginx, MongoDB, Redis, ClickHouse, montaje de discos, Supervisor, Cron, Firewall DNS. Contar con conocimientos en CloudFlare (WAF, Rate Limits), será un plus! Inglés técnico intermedio Ser estudiante o Profesional universitario de las carreras de ingeniería en sistemas, informática, telecomunicaciones o afín.¿Qué vas a hacer? Mantener operativa la plataforma Garantizar la performance y seguridad del sistema. Asegurar la disponibilidad de guardias pasivas o contacto de emergencia Crear entornos segregados Desarrollar una política de backup escalable Creación de planes de disaster recovery Prever posibles cambios presupuestarios de infraestructura¿Cuál es el desafío de la posición?Junto al Cloud Engineer y al equipo de desarrollo, tendrás por delante el desafío de terminar de implementar CI/CD, cultura de automatización y migraciones de sistemas operativos core y entornos en la nube en su totalidad.¿Con quién trabajarás?Trabajarás en conjunto con el referente del área.¿Cuándo y dónde trabajarás?Trabajarás en el horario de 9 a 18 hs, en un esquema híbrido asistiendo dos días a las oficinas ubicadas en Parque Patricios – martes y miércoles – y 3 días de home offices. La posición cuenta con un esquema de Guardias de 2 semanas por mes.¿Qué ofrecen? Relación de dependencia directa con la empresa. Prepaga de primer nivel. Día de cumpleaños libre + regalo especial. Viernes Flex: 1 viernes al mes con media jornada. 21 días de vacaciones. Happy Summer: 2 fines de semana largos libres en verano. Tarjeta prepaga con crédito mensual. Club de beneficios con descuentos exclusivos. Descuentos en Educación IT.¿De qué fases consta el proceso de selección?Tendrás una primera entrevista con nuestra recruiter, Carla Carrizo, para conocer tus experiencias laborales e intereses. Luego, participarás de dos entrevistas con nuestro cliente, conociendo primero al Líder Técnico (Cloud Engineer), y luego una segunda instancia en donde conocerás al CTO-CEO más una persona de HR.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 16:17:31', '09-04-2026 16:17:31', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2625, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_570364_bum_v183b0a04.jpg', 0, 0, NULL, 1020, 'Aviso Select', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179290.html', '2026-04-13T07:05:55.114977');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226888, 13379526, 'Analista de Compras y Administración / Asistente de Administración General', 'HOLZBODEN', 'Analista de Compras y Administración / Asistente de Administración GeneralResumen del PuestoBuscamos profesionales con experiencia en Análisis de Compras y Administración JR., así como en Asistencia de Administración General. El candidato ideal poseerá habilidades analíticas sólidas, capacidad para la toma de decisiones estratégicas y una gestión eficiente de recursos. Se valorará la proactividad y la orientación a resultados.Responsabilidades Principales Realizar el análisis de tableros de ventas para optimizar la reposición de productos. Gestionar y supervisar las operaciones de administración general. Colaborar en la planificación y ejecución de estrategias de compras. Asegurar la eficiencia en los procesos administrativos y de aprovisionamiento. Identificar oportunidades de mejora en la cadena de suministro y gestión de inventarios.Requisitos del Perfil Estudiante avanzado o graduado en áreas afines a Administración, Compras, Actuario o carreras técnicas relacionadas. Experiencia comprobable en análisis de datos de ventas y gestión de inventarios. Conocimiento en procesos de compras. Habilidades avanzadas en el uso de herramientas de análisis y gestión (ej. Excel, software ERP Indicar cual ha usado). Capacidad para trabajar de forma autónoma y en equipo, con excelentes habilidades interpersonales. Orientación al detalle y rigurosidad en la gestión administrativa.Modalidad de Trabajo Hibrida (mix presencial y remoto o puede ser 100% remoto en caso de estar en otra provincia)- Lugar de trabajo: Palermo – CABA.- Excelente clima laboral y posibilidades de crecimiento.- Horario: 2 PUESTOS DE TRABAJO EN BUSQUEDA. Uno PART TIME Y otro FULL TIME. Horario Part Time: 5hs en horario a convenir dentro de 8.30 a 18.30 hs Lun a Vie. Horario Full Time: 9:00 a 18:00 (se puede adaptar el horario a 8.30 a 17.30 o 9.30 a 18.30 )Indicar remuneracion pretendida y a cual puesto aplica, si part time o full time y disponibilidad horaria', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '10-04-2026', '10-04-2026 13:14:42', '10-04-2026 13:35:41', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 3, 56, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13379526_bum_v8bf35b69.jpg', 0, 0, NULL, 40, 'Destacados', 'bumeran', 'destacado', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226888.html', '2026-04-13T07:05:55.115137');
