INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226628, 13017284, 'Gerente de Operación Terrestre – Turismo B2B', 'Darwin Consulting - Evolución Empresarial', '#TURISMOGerente de Operación Terrestre – Turismo B2BNegociación con proveedores | Gestión de producto turístico | Optimización de márgenesPara una compañía en expansión líder del sector turístico con presencia en mercados nacionales e internacionales, especializada en la intermediación y comercialización de servicios de viaje para agencias, buscamos incorporar un/a Gerente de Operación Terrestre con responsabilidad integral sobre esta vertical de negocio.La empresa opera en un entorno dinámico, gestionando una amplia cartera de productos turísticos que incluyen alojamiento, excursiones, experiencias y paquetes terrestres, tanto en Argentina como en destinos internacionales. Su modelo de venta es B2B (agencias de turismo y empresas), con foco en competitividad, eficiencia operativa y desarrollo comercial.La posición tendrá como misión liderar la estrategia y ejecución de la operación terrestre, asegurando rentabilidad, posicionamiento de producto y calidad en la propuesta al mercado.Responsabilidades principales Liderar la gestión integral de la vertical de operación terrestre (hoteles, excursiones, espectáculos, paquetes y otros servicios no aéreos). Negociar acuerdos comerciales con proveedores nacionales e internacionales. Definir y dar seguimiento a variables clave del negocio: precios, márgenes, condiciones comerciales y eficiencia operativa. Analizar y optimizar la rentabilidad de los productos y servicios ofrecidos. Configurar la oferta comercial para mejorar competitividad y ganar participación de mercado. Asegurar el correcto posicionamiento de los productos lanzados al mercado. Coordinar con áreas comerciales y de producto para alinear estrategia y ejecución. Reportar directamente a la dirección de la compañía.Perfil buscado Experiencia previa en el sector turístico, preferentemente en operadores, mayoristas o agencias con operación terrestre. Experiencia en negociación con proveedores turísticos (hoteles, receptivos, operadores locales). Capacidad de análisis de negocio orientada a margen, pricing y eficiencia. Experiencia en gestión de producto turístico y configuración de oferta. Nivel de inglés fluido para negociación y gestión internacional. Perfil autónomo, con visión estratégica y fuerte capacidad de ejecución.Condiciones del puesto Ubicación: Buenos Aires. Modalidad: presencial con asistencia mínima de 3 días por semana. Compensación: salario fijo más variable competitivo en función de resultados. Posición con responsabilidad directa sobre resultados de negocio. Disponibilidad para viajar al interior y exterior del país', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '10-04-2026', '10-04-2026 16:05:10', '10-04-2026 16:05:10', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 10, 2360, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13017284_bum_v1bebd138.jpg', 0, 0, NULL, 10, 'Home', 'bumeran', 'home', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226628.html', '2026-04-13T07:05:55.115805');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227350, 1127240, 'Bacheros para Hotel 5 estrellas CABA', 'Adecco Argentina -Región Office', 'Adecco Hoteles y Catering es la división especializada en el reclutamiento, selección, evaluación, formación y puesta a disposición de profesionales para empresas del sector hotelería y catering de eventos.Si te gustan los desafíos y sos una persona comprometida,¡Tenemos una oportunidad para vos!Estamos buscando STEWARDS - BACHEROS para importante Hotel ubicado en RETIRO.Los requisitos son: · Disponibilidad para realizar horarios rotativos (EXCLUYENTE) . Disponibilidad semanal · Experiencia en el puesto, preferentemente en hoteles de primera categoría. · Actitud y responsabilidad.Se ofrecen muy buenas condiciones de contratación y posibilidades de estabilidad a largo plazo en una empresa de primer nivel.El compromiso de Adecco, es promover y mantener la cultura del respeto e igualdad de oportunidades. No discriminamos en función del género, religión, etnia, nacionalidad, cultura, grupo social, discapacidad o enfermedad, orientación sexual, estado civil, edad u opinión política. Cuando elegimos el personal para un cliente, la decisión se basa única y exclusivamente en los méritos y capacidades de esa persona.¡TRANSFORMÁ TU TALENTO EN EXPERIENCIA! APOSTÁ AL CAMBIO, NOSOTROS APOSTAMOS POR VOSAdecco no solicita dinero a cambio de sus servicios. Participar de una búsqueda con nosotros es parte de nuestro compromiso y tarea. Por ello, postularte y participar en una oferta de empleo, es GRATIS.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 16:31:47', '11-04-2026 17:05:30', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 4, 0, 10, 2350, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_1127240_bum_vd8d10d9e.jpg', 1, 1, 4.08, 70, 'Simples', 'bumeran', 'simple', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227350.html', '2026-04-13T07:05:55.115935');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118144323, 13504754, 'Administración de Back Office - Gestión de Servicios', 'SBG', 'Asistente de Back Office - Gestión de ServiciosResumen del PuestoBuscamos un perfiles con orientación a Back Office y conocimientos administrativos para integrarse a nuestro equipo y colaborar activamente en la gestión de servicios.Responsabilidades Establecer contacto telefónico con clientes. Colaborar con el equipo técnico en la resolución de asistencias de servicios. Realizar el control y seguimiento de los servicios asignados. Confección de ruteo diarios para técnicos. Coordinar la derivación diaria de servicios y elaborar informes de gestión.Requisitos Formación avanzada en Administración de Empresas o similar. Dominio del paquete Office y herramientas de gestión. Alta proactividad y capacidad de autogestión. Habilidad para interpretar y resolver incidencias. Experiencia mínima de 2 años en roles similares. Rango etario 2 5 hasta 3 5 años. Preferentemente sexo femenino.Condiciones de Trabajo Modalidad de trabajo Prescencial. Jornada laboral de lunes a viernes de 0 8: 0 0 a 1 7: 0 0 hs.', 0, 'Ciudad Madero, Buenos Aires', 'Presencial', 'Full-time', '12-04-2026', '12-04-2026 18:28:17', '12-04-2026 18:30:20', '2026-04-12', NULL, NULL, '2026-04-12T00:00:00-03:00', NULL, NULL, 1, 0, 36, 1, 1, NULL, NULL, NULL, NULL, 750, 'Aviso Express', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118144323.html', '2026-04-13T07:05:55.116048');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179413, NULL, 'Back Office de Tesorería Jr.', 'Confidencial', 'Para importante compañía nacional líder en su rubro, nos encontramos en la búsqueda de un/a Back Office de Tesorería.Si sos estudiante de Ciencias Económicas y te interesa desarrollar tu carrera profesional en áreas administrativas dentro de una compañía pujante, ¡esta es una gran oportunidad para vos!El objetivo del puesto serán todas las actividades administrativo-contables vinculadas con la caja, transacciones bancarias e inversiones de la empresa.Las tareas principales:- Operaciones de caja: Recibir valores por cobranzas directas, controlarlos, emitir y firmar los recibos a fin de permitir su correcta registración. Registrar e ingresar los valores de caja. Custodiar los valores de caja (cheques de terceros, efectivo). Confeccionar cheques para el pago a proveedores, siniestros, impuestos, comisiones a productores e intermediarios y rendiciones de gastos.- Operaciones bancarias: Coordinar los trámites bancarios a realizar por el cadete. Preparar para su depósito los cheques en condiciones de ser depositados, efectuando su pertinente endoso y la confección de boletas de depósito que respalden las registraciones contables. Controlar diariamente los cheques emitidos aún pendientes de ser debitados. Contabilizar los cheques rechazados y posteriormente ingresar los nuevos valores recibidos en su reemplazo. Obtener la información diaria de las posiciones bancarias, controlando sus saldos y movimientos, y comunicarla a la Gerencia de Administración y Finanzas y a la Dirección Ejecutiva. Interactuar y operar por medios electrónicos con entidades bancarias.Nos orientamos a un/a estudiante universitario/a de Cs. Económicas que se encuentre promediando la carrera, con al menos un año de experiencia en tareas de tesorería, manejo intermedio de Excel, buen manejo de información confidencial y actitud para incorporar nuevas tecnologías.Es una gran oportunidad por las buenas condiciones de contratación: Puesto efectivo por tiempo indeterminado en relación de dependencia. Modalidad híbrida luego de un primer período de presencialidad full. Jornada full time, de lunes a viernes de 9 a 18 hs. Zona Centro de CABA. Excelente paquete de beneficios.', 1, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '10-04-2026', '10-04-2026 16:42:45', '10-04-2026 16:42:45', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 1, 1, 2597, 1, NULL, NULL, NULL, NULL, 70, 'Avisos Classic', 'zonajobs', 'zonajobs', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179413.html', '2026-04-13T07:05:55.116192');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227498, 1013630, 'Operador de Call Center Junior- Contratación Directa- Entidad Bancaria', 'ACCIONA IT', 'En Acciona IT nos encontramos en búsqueda de un profesional para desempeñarse como Operador de Call Center Junior para una importante entidad bancaria.Requisitos excluyentes:Experiencia de 1 año como Operador de Call CenterExperiencia comercialExperiencia en ventas de segurosEstudiantes de carreras universitarias: económicas, marketing, recursos humanos, sistemas. ( excluyente)Part-time:Horario de 14:00 a 19:00 hsEsquema presencial en Barracas.Contratación directa con el cliente', 0, 'Buenos Aires, Buenos Aires', 'Presencial', 'Part-time', '10-04-2026', '10-04-2026 17:33:28', '10-04-2026 17:33:28', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_1013630_bum_v9c1aa214.jpg', 1, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 1, 0, NULL, 'https://certificaciones.greatplacetowork.com.ar/acciona-it', 'https://www.bumeran.com.ar/empleos/1118227498.html', '2026-04-13T07:05:55.116280');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2178990, 524103, 'Mozo/a de Barra', 'Galidon', 'Mozo/a de Barra Resumen del Puesto Buscamos un/a Mozo/a de Barra dinámico/a y con vocación de servicio para integrarse a nuestro equipo. Si disfrutas del trato con el público y tienes experiencia en el sector gastronómico, esta oportunidad es para ti. Responsabilidades Atención al cliente en barra. Toma y entrega de pedidos. Preparación de bebidas sencillas. Mantenimiento del orden y la limpieza del área de trabajo. Coordinación con el personal de cocina y salón. Requisitos Experiencia previa en puestos similares (valorada). Buena presencia y excelente trato interpersonal. Agilidad, responsabilidad y compromiso. Habilidad para trabajar en equipo. Disponibilidad horaria. Ofrecemos Un ambiente de trabajo agradable. Oportunidades de desarrollo profesional. Incorporación inmediata.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 10:02:25', '07-04-2026 10:02:25', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 10, 2350, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_524103_bum_v5ee0d0e1.jpg', 0, 0, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2178990.html', '2026-04-13T07:05:55.116375');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118222794, 2302190, 'Coordinador/a de Biblioteca UCA Paraná', 'Fundación Universidad Católica Argentina', 'La Pontificia Universidad Católica Argentina (UCA) es una de las Universidades privadas más antiguas y con mayor prestigio de Argentina. Fue fundada en 1958 y posee cuatro sedes en el país, ubicadas en las ciudades de Buenos Aires, Rosario, Mendoza y Paraná. La Universidad promueve la formación académica con una visión humanista y cristiana tendiente al logro de profesionales altamente capacitados, dispuestos a asumir responsabilidades, con fuerte espíritu innovador y creativo, en una actitud abierta, y de servicio a la comunidad.Según el QS World University Rankings 2026 la UCA se consolida como la primera universidad privada en la Argentina por séptimo año consecutivo y se ubica dentro del Top 550 a nivel mundial. De esta manera, la UCA se encuentra en la posición 517 y ocupa el primer puesto entre las universidades privadas y el tercero entre las argentinas. La Facultad “Teresa de Ávila” se encuentra en búsqueda de un/a Coordinador/a para liderar la Biblioteca de la Sede Paraná, dependiente del Sistema de Bibliotecas de la UCA (SIBUCA). Las principales tareas del puesto son: Coordinar el equipo de trabajo y la operación integral de la Biblioteca. Liderar la planificación estratégica y la gestión presupuestaria de la Biblioteca. Implementar las políticas y lineamientos definidos por SIBUCA. Supervisar la organización, conservación y actualización de las colecciones físicas y digitales. Impulsar proyectos de innovación y mejora continua de servicios. Representar a la Biblioteca en redes académicas y espacios institucionales. Dar seguimiento a los procesos de evaluación de los servicios. Participar en los procesos de evaluación institucional (CONEAU). Requisitos: Experiencia: Mínimo 3 años en gestión de unidades de información o bibliotecas académicas (no excluyente). Experiencia en la planificación, desarrollo e implementación de servicios bibliotecarios, colecciones y proyectos de digitalización. Conocimientos: Normas de catalogación y clasificación (MARC, RDA, CDU). Herramientas tecnológicas aplicadas a bibliotecas (OPAC, repositorios digitales, acceso abierto). Gestión de colecciones y servicios orientados a usuarios. Fuerte orientación a la atención al usuario y a la calidad de los servicios. Capacidad para elaborar y gestionar presupuestos. Nivel mínimo de educación: Título Universitario de Bibliotecología o afín Beneficios 5 semanas de vacaciones anuales. Plataforma de idiomas e-learning gratuita. Capacitación continua en gestión bibliotecaria y tecnologías. Posibilidad de desarrollo profesional dentro del Sistema de Bibliotecas UCA.', 0, 'Paraná, Entre Ríos', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 07:13:12', '10-04-2026 07:13:12', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 9, 120, 1, NULL, 1, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118222794.html', '2026-04-13T07:05:55.116545');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2178998, 679135, 'Asesor Comercial Inmobiliario con experiencia- Rosario y alrededores', 'Desanzo Bienes Raices', 'Asesor Comercial InmobiliarioResumen del PuestoNos encontramos en una etapa de expansión y buscamos incorporar Asesores Comerciales Inmobiliarios con experiencia comprobada en el sector. Esta oportunidad está dirigida a profesionales que buscan desarrollarse dentro de una estructura sólida, con herramientas de apoyo y claras posibilidades de crecimiento profesional.Responsabilidades Gestionar y dar seguimiento a la cartera de clientes. Identificar y desarrollar nuevas oportunidades de negocio. Comercializar propiedades y desarrollos inmobiliarios. Utilizar plataformas digitales y redes sociales como herramientas de captación. Cumplir con los objetivos comerciales establecidos.Requisitos Experiencia previa en el rubro inmobiliario (excluyente). Perfil comercial, proactivo y con orientación a resultados. Habilidad para el manejo de redes sociales y herramientas digitales. Capacidad de organización y autonomía en la gestión.Ofrecemos Capacitación continua en el sector. Acompañamiento y soporte en la gestión comercial. Herramientas y una estructura de trabajo que facilita el desarrollo. Flexibilidad y oportunidades de crecimiento profesional.', 0, 'Rosario, Santa Fe', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 16:26:50', '08-04-2026 16:26:50', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 6, 23, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_679135_bum_vf12d31fe.jpg', NULL, NULL, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2178998.html', '2026-04-13T07:05:55.116652');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2177641, 678955, 'Coordinador de Emergencias Médicas Aéreas y Desarrollo de Negocios (bilingüe)', 'IMPACTO TALENT', 'Young aeronautical company specializing in air ambulance and medical escort services. Recognized in the Great Place to Work rankings, committed to safety, excellence, and a great work environment. This is an opening to work on Saturdays, Sundays and Holidays, 00:00 AM–12:00 PM.The goal of this position is to attend to urgencies and proactively carry out operational and business development tasks.Key responsibilities include: Operational support: Coordinate missions and assist with logistics to ensure service continuity and timely response. Business development: Building and maintaining a network of providers, partners, or clients relevant to the aviation industry. Sending outreach emails and initiating contact with potential clients or partners, primarily targeting the Asia time zone based on a pre-defined contact list. Taking advantage of the quieter hours to advance administrative or operational tasks, such as updating databases, researching potential leads, or coordinating logistics. Requisitos: Requirements: Location: CABA/GBA (availability to work in Palermo). Fluent level of spoken English. Experience in similar position: Operador/a de Emergencias / Urgencias — Emergency / Urgent Care Operator /Emergency Dispatcher Coordinador/a de Emergencias Médicas — Medical Emergency Coordinator Coordinador/a de Casos Médicos / Asistencia Médica — Medical Case Coordinator / Medical Assistance Coordinator Ejecutivo/a de Asistencia al Viajero — Travel Assistance / Travel Support Executive (Travel Assistance Officer) Analista de Asistencia / Claims — Assistance Analyst / Claims Analyst Medical Case Manager — Medical Case Manager Operations Coordinator / Specialist (en contexto de asistencia médica) — Operations Coordinator / Operations Specialist (medical assistance context) Beneficios Direct Hiring by the Company Monthly salary updates Professional Development Welcome kitThis is a direct hire opportunity — you will be hired directly by the company.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '17-03-2026', '17-03-2026 11:40:23', '10-04-2026 15:52:59', '2026-03-17', NULL, NULL, '2026-03-17T00:00:00-03:00', NULL, NULL, 2, 0, 1, 22, 1, NULL, NULL, NULL, NULL, 1020, 'Aviso Select', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2177641.html', '2026-04-13T07:05:55.116796');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118221100, 17250, 'Analista de Atención Bioquímica', 'Cibic Laboratorios', 'Somos un laboratorio enfocado en el diagnóstico clínico y en el desarrollo de la biotecnología, situado en Rosario y en Funes, provincia de Santa Fe, con más de 30 años de experiencia en diagnóstico de la salud. Conforman nuestro equipo de trabajo más de 300 personas, distribuidas en nueve Centros de Atención a Pacientes, en el Centro de Producción, Investigación y Desarrollo (CEPIDE) y en el Centro de Almacenamiento y Logística. Contamos con profesionales especializados, equipos de última tecnología y un sistema de gestión integrado. Somos laboratorio de referencia nacional por la innovación tecnológica y por los estándares de nuestros servicios. ¡Estamos en búsqueda de un/a Analista de Atención Bioquímica! ¿Querés formar parte de un equipo que hace la diferencia? Sumate a nuestro equipo y trabajá en un ambiente profesional, dinámico y enfocado en la mejora continua.️ Responsabilidades principales Asesorar a pacientes y médicos en consultas bioquímicas. Colaborar con áreas clave del laboratorio para garantizar la mejor atención. Participar en proyectos de investigación y auditorías. Velar por la seguridad, integridad y satisfacción de nuestros clientes. Requisitos: Graduados/as en Bioquímica (excluyente ) Profesionales comprometidos/as con la calidad y la ética. Capacidad para analizar, diagnosticar y gestionar estándares de servicio. Ganas de mantenerse actualizados/as en avances científicos y tecnológicos. Horario: lunes a viernes de 13 a 19 - sábados de 7 a 12:30. Beneficios Mutual Grupo Oroño Bonificación en instituciones educativas Día de cumpleaños free + regalo de cumpleaños Descuentos en comercios adheridos y gimnasios Beneficios bancarios Importantes descuentos en seguros ️', 0, 'Rosario, Santa Fe', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 11:10:46', '07-04-2026 11:10:46', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 23, 2639, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_17250_bum_v24d8b615.jpg', 1, 0, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221100.html', '2026-04-13T07:05:55.116939');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2178922, 465901, 'Bioquímicos', 'Swiss Medical', 'En Swiss Medical trabajamos cada día para que las personas vivan más y mejor. Más de 4 millones de personas confían en nosotros y, detrás de cada historia, hay un equipo de más de 16.500 colaboradores que elige todos los días cuidar, acompañar y transformar vidas.Para seguir impactando positivamente en la vida de más personas, buscamos sumar a Bioquímicos en nuestras Clínica Zabala y Clínica y Maternidad Suizo Argentina.🔍 Responsabilidades Procesar y analizar muestras biológicas de manera eficiente y precisa, utilizando técnicas y equipos especializados. Validar e interpretar los resultados de los análisis, asegurando su exactitud y relevancia clínica. Implementar y mantener los estándares de calidad y los procedimientos operativos del laboratorio. Operar y mantener el equipamiento de laboratorio, asegurando su correcto funcionamiento y calibración. Gestionar el stock de reactivos e insumos necesarios para los análisis. Colaborar con otros profesionales de la salud para brindar un servicio integral al paciente. Cumplir con las normativas y regulaciones vigentes en el ámbito de la salud y el laboratorio clínico.🎯 Requisitos Bioquímico con Título Universitario (Finalizado). Contar con Matrícula Nacional. Conocimientos en: Preparaciones para estudios l LIS del laboratorio l Bioseguridad. Experiencia de al menos entre 1 a 3 años en instituciones similares.💫 Beneficios🤝 La posibilidad de crecer en una compañía líder, en constante evolución.📚 Descuentos en Universidades y productos Swiss Medical (seguros, salud, etc.).🏋️‍♀️🏋️‍♂️ Acceso a la Plataforma de bienestar WELLHUB (fitness, mindfulness, nutrición y más).🎁 Descuentos en marcas líderes.📍 Modalidad: Presencial – CABA.Viernes 20 a 8hs. y domingos 8 a 20hs.🚀 Sumate a una compañía que trabaja todos los días para que millones de personas vivan más y mejor.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '06-04-2026', '06-04-2026 11:52:26', '09-04-2026 12:17:43', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 23, 2639, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_465901_bum_v31a94d45.jpg', 1, 0, NULL, 70, 'Avisos Classic', 'zonajobs', 'zonajobs', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2178922.html', '2026-04-13T07:05:55.117117');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179108, 524045, 'Bioquímico de Planta', 'Laboratorio Rapela', 'El laboratorio fue fundado en 1991 en la Ciudad Autónoma de Buenos Aires, en la calle Ramón Falcón 2534. Con una sede de más de 1000 m2 y equipado con tecnología de punta, ofrece servicios de análisis clínicos, toxicológicos, veterinarios, bromatológicos, cosméticos y farmacéuticos, así como también servicios de Clinical Trials, Diagnóstico por imagen y Servicios a Terceros.A lo largo de los años, el laboratorio ha obtenido diversas certificaciones y reconocimientos por su calidad y profesionalismo, incluyendo la Certificación ISO 9001 en el año 2000, la Acreditación ISO 15189 y la Acreditación ISO 17025 en 2005, con sus respectivas re-certificaciones en años posteriores. Además, ha sido reconocido por el COI en varias ocasiones y cuenta con la habilitación de SENASA. En Laboratorio Rapela nos encontramos en la búsqueda de ́/ de planta para el area de Inmunoquimica. Posición Permanente Lugar de trabajo: Flores, CABA Horario: Lunes a Viernes de 13 a 21 hs y sábados por medio de 9 a 13 hs ¿Cuáles serán tus tareas? Procesamiento de muestras en equipos automatizados. Lectura microscopica. Informe y comunicación de resultados críticos. Validación técnica de resultados. Validación final de resultados. Monitoreo de Pendientes. Procesamiento, análisis y validación de controles internos y externos.Requisitos: Bioquimico graduado. Matricula nacional habilitante (no excluyente) Experiencia mínima de dos años en guardia o puestos similares en instituciones de salud.Te ofrecemos: Dia de cumpleaños libre Bonificación en gimnasios de primera línea Convenio con Institutos de idiomas (Liceo Británico/Open English)‍️ Te bonificamos el 100% en tus Análisis Clínicos ¡Tu mascota es familia! 50% en sus Análisis veterinarios Bonificación en academia de manejo para vos y tu familia¡Administra tu sueldo! Anticipamos hasta el 50% a mitad de mes¡Aguardamos tu postulacion! Requisitos:', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 08:54:23', '08-04-2026 08:54:23', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 23, 2639, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_524045_bum_vff225b02.jpg', 1, 0, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179108.html', '2026-04-13T07:05:55.117275');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179116, 648763, 'BROKER INMOBILIARIO', 'Grupo CGS S.A.', '🚀 BÚSQUEDA ACTIVA – ASESOR INMOBILIARIOEn CGS estamos en búsqueda de Asesores Inmobiliarios para sumarse a nuestro equipo.Si te interesa desarrollarte en el rubro, tenés perfil comercial y ganas de crecer, esta es una gran oportunidad.🔹 ¿Qué buscamos? Perfil proactivo y orientado a resultados Buen manejo de relaciones interpersonales Compromiso y responsabilidad Ganas de aprender y desarrollarse🔹 ¿Qué ofrecemos? Acompañamiento y capacitación constante Excelente clima de trabajo Posibilidades reales de crecimiento Esquema de ingresos competitivo📍 Modalidad: [PRESENCIAL - Lunes a sabados de 09:30 a 17:30]Si querés formar parte de un equipo en crecimiento, envianos tu CV.', 0, 'Munro, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 09:56:19', '08-04-2026 09:56:19', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 5, 1, 6, 23, 1, NULL, 0, 0, NULL, 40, 'Avisos Gold', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179116.html', '2026-04-13T07:05:55.117388');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2178862, 638730, 'Referente Comercial - Broker de Seguros', 'SegurÚ', 'Referente Comercial - Seguros PatrimonialesResumen del PuestoEstamos en la búsqueda de un/a Referente Comercial, Preferentemente con Matrícula de Productor de Seguros. con experiencia comprobada en el sector de seguros patrimoniales. El objetivo principal será liderar y potenciar el desarrollo de nuestros diversos canales comerciales, impulsando el crecimiento y la expansión del negocio.La posición requiere un perfil con fuerte orientación comercial y capacidad de gestión integral,Ofrecemos un entorno dinámico, con fuerte impronta tecnológica (uso de IA y herramientas de gestión), trabajo en equipo, capacitación continua y posibilidades de crecimiento dentro de una organización en expansión.Responsabilidades Principales Ser referente comercial en el desarrollo de los distintos canales comerciales. Interactuar con funcionarios de las distintas compañías de seguros con las que estamos aliados estratégicamente. Interactuar con la cartera actual de clientes. Interactuar con el canal de PASRequisitos del Puesto Experiencia amplia en la gestión de seguros patrimoniales. Se prefiere matrícula de productor de seguros. Manejo de Microsoft Office, ambiente Google. Experiencia en el manejo de CRMs y herramientas digitales de gestión. Conocimiento de herramientas de inteligencia artificial y de automatizaciónes. Disponibilidad horaria.¿Qué ofrecemos? Cultura y excelente ambiente laboral. Trabajo en equipo con planes de acción. Entrenamiento continuo y aplicación de procesos. Capacitación y cursos. Ambiente muy involucrado con inteligencia artificial y paneles de gestión. IA Primero Manejo de herramientas tecnológicas. Sueldo acorde a la responsabilidad. Trabajo híbrido (presencial y home office).', 0, 'Mendoza, Mendoza', 'Presencial', 'Full-time', '06-04-2026', '06-04-2026 16:51:13', '06-04-2026 16:51:13', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 6, 23, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_638730_bum_v20262afc.jpg', 0, 0, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2178862.html', '2026-04-13T07:05:55.117530');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2157206, NULL, 'Asistente Jr Broker de Seguros', 'Confidencial', 'Estamos creciendo y buscamos sumar a un asistente de Back Office!Si sos una persona comprometida, con ganas de sumarte a un equipo, desarrollar tareas remotas y presenciales, capacitarte, compartir nuestro espíritu emprendedor adaptándote a las nuevas tecnologías, te estamos esperando!Creemos en lugares de trabajo inclusivos para que todos nuestros colaboradores puedan desarrollar plenamente sus talentos, por lo que nos encantaría que adultos mayores y personas con discapacidad y la experiencia que requerimos se postulen! De necesitar algun requerimiento especial para hacerlo, por favor escribinos a mariana@reclamoweb.comTus tareas serán el control de Procesos digitales que involucran cotización, emisión, control, descargas de interfases, capacitación a nuevos miembros del equipo y administración de siniestros. Valoramos experiencia en Caucion comprobable.Somos una pyme no obstante estamos bastante diferenciados en tareas por lo que trabajamos en equipo y el hecho de que tengas habilidades para hacerlo es lo que mas consideramos ya que es el éxito de nuestro trabajo remoto.Esperamos tus antecedentes indicando riesgos y companias con las que tenes experiencia! EXPERIENCIA & REFERENCIAS COMPROBABLES (excluyentes).Sumate!Gracias!', 1, 'Pilar, Buenos Aires', 'Remoto', 'Full-time', '06-04-2026', '06-04-2026 17:04:28', '12-04-2026 15:16:50', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 1, 28, 2410, 1, NULL, NULL, NULL, NULL, 70, 'Avisos Classic', 'zonajobs', 'zonajobs', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2157206.html', '2026-04-13T07:05:55.117653');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2178848, 679115, 'Asistente Administrativo - Sector Seguros', 'Habif Broker', 'Asistente Administrativo - Sector SegurosResumen del PuestoBuscamos un/a Asistente Administrativo con experiencia y conocimientos en la industria de seguros (Excluyente) para integrarse a nuestro equipo. La persona seleccionada se orientará al sector de cobranzas, desempeñando tareas administrativas y de gestión.Responsabilidades Gestión de tareas administrativas generales. Soporte en el área de cobranzas. Manejo de documentación y archivo. Colaboración en la gestión de operaciones del sector. Comunicación efectiva con diferentes áreas.Requisitos Experiencia previa comprobable en puestos administrativos. Conocimiento y experiencia en la industria de seguros (excluyente). Habilidades de comunicación efectiva. Capacidad para el manejo de tareas de oficina y equipamiento básico. Autonomía y capacidad para trabajar en equipo. Modalidad de trabajo híbrida.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '06-04-2026', '06-04-2026 16:47:39', '06-04-2026 16:47:39', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 28, 2552, 1, NULL, NULL, NULL, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2178848.html', '2026-04-13T07:05:55.117761');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226435, NULL, 'Asistente de Depósito | Ciudad Autónoma de Buenos Aires', 'Confidencial', 'Importante empresa del rubro industrial busca incorporar un Asistente de Depósito para desempeñarse en la Ciudad Autonóma de Buenos Aires.PRINCIPALES TAREAS: Carga y descarga de mercaderia Paletizado Control de stock Control de documentaciónREQUISITOS PARA LA POSICION: Vivir en CABA Experiencia minima 3 años en la posición Contar con licencia de conducir vigente Manejo de autoelevador (deseable) Perfil autónomo, proactivo con buenas relaciones interpersonales.¡Si crees que esta oportunidad es para vos, esperamos tu postulación!', 1, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '10-04-2026 01:04:07', '10-04-2026 01:04:07', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 3, 2638, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226435.html', '2026-04-13T07:05:55.117869');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227917, 319880, 'HRBP Generalista Soft (LIMA/ZARATE, Buenos Aires, jornada presencial)', 'Randstad Argentina', '¡Esta propuesta te puede interesar! HRBP (Lima/Zarate, Buenos Aires, jornada presencial) Para nuestro cliente, importante empresa líder en logística automotriz con base en el Puerto de Lima (Zárate), nos encontramos en la búsqueda de una HRBP con enfoque Generalista/Soft. Orientamos la búsqueda a un perfil con capacidad de negociación y vocación de servicio para liderar el cambio cultural. El Objetivo principal será liderar la gestión de recursos humanos en la sede de Lima y playas externas, asistiendo a la Jefatura Nacional en los procesos de atracción de talento, desarrollo y comunicación, sin descuidar la armonía en las relaciones laborales. Responsabilidades: Liderar los procesos de reclutamiento y selección local: filtrado de CVs, entrevistas de preselección y coordinación de ingresos. Ejecutar el programa de onboarding e inducciones presenciales para garantizar una bienvenida cálida y profesional. Gestionar las relaciones laborales diarias con delegados gremiales, manteniendo una postura firme y profesional. Realizar visitas mensuales a las playas externas cercanas para medir el clima laboral y mantener contacto con los operadores. Administrar novedades de personal y documentación legal necesaria para el acceso a terminales portuarias. Brindar soporte y respuesta inmediata a las consultas del cliente interno (recibos de sueldo, beneficios, etc.). Colaborar en el diseño de comunicaciones internas y planes de capacitación anual. Requisitos: Formación: Lic. en Recursos Humanos, Relaciones Laborales, Psicología o carreras afines. Experiencia: Mínimo 3 años en roles de HRBP o Generalista de RRHH, preferentemente en entornos operativos/industriales. Habilidades: Marcada experiencia en negociaciones sindicales y resolución de conflictos (Excluyente). Herramientas: Microsoft Office (Excel intermedio/avanzado) y sistemas de gestión. Residencia: Zona Zárate, Campana, Lima o alrededores Otros: Licencia de conducir vigente para traslado entre playas con el vehículo corporativo de manera ocasional. Jornada y Modalidad: Lunes a viernes de 08:00 a 17:00 hs. Modalidad: 100% Presencial. Beneficios: Prepaga y Comedor incluido y otros beneficios importantes. Si consideras que reunís los requisitos para el puesto y te gustan los desafíos, no lo dudes…. ¡Postulate! Sobre Randstad En Randstad nos moviliza ayudar a las personas y a las organizaciones a desarrollar todo su potencial. Ese es el compromiso que asumimos como compañía en todo el mundo, un compromiso que nos impulsa a ir más allá para lograr que nuestros clientes y candidatos alcancen el éxito. ¿Cómo lo hacemos?, combinando nuestra pasión por las personas con el poder de la tecnología, creando experiencias más humanas, que nos permitan ser una fuente de inspiración y apoyo para quienes nos eligen. Porque estamos convencidos de que mejores personas hacen mejores.', 0, 'Tortuguitas, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 20:48:00', '13-04-2026 04:03:46', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 22, 36, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_319880_bum_vff58225f.jpg', 1, 0, 4.28, 70, 'Simples', 'bumeran', 'simple', 1, 0, 1, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227917.html', '2026-04-13T07:05:55.118074');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179161, 570364, 'Business Intelligence Senior (Data Planning) - Híbrido - 1822', 'Aliantec', '¿Qué hace la compañía?Compañía nativa digital con presencia global de gran escala de ingeniería, diseño e innovación, con sedes ubicadas en diferentes países de América, Asia y Europa. Cuenta con presencia en 18 países y con un equipo de más de 20 mil profesionales que forman parte de nuevos desafíos y proyectos de vanguardia¿Qué necesitás para ser parte del equipo?A nivel personal: Capacidad analítica y orientación a resultados. Autonomía y proactividad en la gestión de tareas. Buenas habilidades de comunicación para interactuar con perfiles técnicos y de negocio. Organización y manejo de múltiples prioridades.A nivel técnico: Contar con 10 años de experiencia en roles de datos/BI/analytics. Experiencia sólida en Business Intelligence en nivel Senior. Dominio avanzado de SQL (excluyente). Experiencia trabajando con Google BigQuery. Experiencia en diseño, desarrollo y optimización de procesos ETL. Conocimiento en modelado de datos orientado a negocio (planeamiento y revenue). Experiencia trabajando con grandes volúmenes de datos.Es un plus: Experiencia en herramientas de visualización como Looker. Interés o experiencia en GenAI (IA Generativa).¿Qué vas a hacer?Como Business Intelligence Senior, vas a tener un rol clave en la generación de valor estratégico a partir de los datos. Entre tus principales responsabilidades estarán: Liderar la asignación de ingresos a nuevas unidades de negocio o productos, asegurando la correcta visibilidad financiera del crecimiento. Desarrollar y optimizar modelos analíticos enfocados en planeamiento y atribución de revenue. Traducir necesidades complejas del negocio en soluciones de datos accionables. Colaborar con equipos de Producto, Tecnología y Negocio para comunicar insights y recomendaciones. Identificar oportunidades de mejora continua en procesos y automatización de la atribución. Documentar procesos y flujos de datos para asegurar su correcta comprensión y replicabilidad.¿Cuándo y dónde trabajarás?La posición se desarrolla bajo una modalidad híbrida, con asistencia presencial deseable una vez por semana en oficinas ubicadas en Capital Federal, Buenos Aires¿Qué ofrecen? Sueldo split: gran porcentaje de la remuneración en dólares. Contrato directo con la Empresa. Prepaga de primer nivel para vos y tu grupo familiar. Plataforma de cursos gratuitos. Licencia de paternidad/maternidad extendida. Descuentos en entidades educativas privadas. Tarjeta de descuentos: ropa, comida, viajes, etc. Inglés in Company. Plan de carrera interno en diferentes ramas IT. Proyectos multidisciplinarios.¿De qué fases consta el proceso de selección?El proceso de selección se desarrolla en varias etapas. En primer lugar, tendrás una entrevista con nuestra Recruiter, Aldana Alvarenga, donde conversaremos sobre tu experiencia laboral y tus intereses.Luego, con la empresa empleadora tendrás otras instancias. La primera una entrevista con el HR de la compañía para conocer más sobre el desafío y screening en inglés, la segunda una evaluación técnica para conocer con profundidad tus conocimientos y por último instancias con el cliente orientadas a conocer al equipo y el proyecto en mayor detalle.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '08-04-2026', '08-04-2026 14:08:27', '08-04-2026 14:08:27', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2620, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_570364_bum_v183b0a04.jpg', 0, 0, NULL, 1020, 'Aviso Select', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179161.html', '2026-04-13T07:05:55.118261');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227863, 10202110, 'GERENTE CONTABLE - CABA', 'RH Talentum', 'Importante empresa del rubro Cosmética/Consumo Masivo, ubicado en CABA, se encuentra en la búsqueda de un/a Gerente de Contabilidad e Impuestos.Buscamos un perfil analítico, con sólida experiencia técnica y capacidad de liderazgo para asegurar el cumplimiento fiscal y la excelencia en la información contable y financiera de las distintas sociedades del grupo.Responsabilidades principales: Liderar la gestión contable e impositiva integral de las sociedades del grupo. Liquidación y presentación de impuestos nacionales y provinciales (IVA, IIBB, SICORE, percepciones/retenciones, RG 4120). Elaboración de balances contables y estados financieros (incluyendo ajuste por inflación). Supervisión de liquidación de sueldos y cargas sociales (F931 y Libro de Sueldos Digital). Gestión de vencimientos, VEP, pagos impositivos y presentaciones ante organismos (AFIP, ARBA, IGJ, BCRA). Atención de inspecciones fiscales y requerimientos impositivos.Requisitos: Formación: Contador Público Nacional (Graduado). Experiencia: Mínima de 5 años en posiciones de liderazgo contable e impositivo. Sistemas: Manejo avanzado de sistema Tango (Excluyente). Conocimientos técnicos: Sólida actualización en normativa fiscal argentina y confección de balances con ajuste por inflación. Perfil: Persona analítica, organizada, con autonomía, criterio profesional y gran sentido de la responsabilidad para gestionar múltiples vencimientos.Condiciones de trabajo: Modalidad: Presencial. Ubicación: CABA - Recoleta. Jornada: Lunes a Viernes de 9.00hs a 17.30hs.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 20:12:40', '12-04-2026 21:27:29', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 1, 58, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/1/0/2/0/2/1/1/0/logoMainPic_10202110.jpg', 1, 0, 3.7, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227863.html', '2026-04-13T07:05:55.118395');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223399, 1476590, 'Administrativo Técnico*CABA*', 'Zivot Consultora en RH', 'Para empresa de Ingenieria , obras eléctricas y soluciones tecnologicas estamos en búsqueda de un administrivo. técnico Se requiere: experiencia en posición similar no inferior a 3 años, será valorada la experiencia en tareas administrativas en obras, tecnicos mécanicos, electromecanicos, electricos. Sus principales responsabilidades serán:Tareas administrativas en general, atención a proveedores, recepción y control de documentación de obra, manejo de caja chica, realizar compras chicas de insumos de Obra (pasar a retirarlos), recepción de facturas, remitos, atención telefónica, procesar datos de ser necesario (por ejemplo ingreso de facturas), chequear mails y comunicaciones varias. Buen manejo de Excel, mails, y demás herramientas informáticas.Se requiere registro de conducir categoria camionetas ( excluyente). Horario de Lunes a Sábados de 8 hs a 18 hs.Ingreso directo por empresa + buena remuneración acorde al puesto + almuerzo + medicina pre-paga primer nivel.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 13:09:53', '10-04-2026 10:09:50', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 4, 2500, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/0/1/4/7/6/5/9/0/logoMainPic_1476590.jpg', 0, 0, 4.85, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223399.html', '2026-04-13T07:05:55.118514');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118219978, 13377015, 'Técnico en Refrigeración - CABA', 'Patagon Water Group', '📢 Búsqueda: Técnico en RefrigeraciónNos encontramos en la búsqueda de un Técnico en Refrigeración para sumarse al equipo de Servicio Técnico de HoReCa - AQA, Hielogic & AQAOffice, dentro de la industria de la purificación de agua 💧.Buscamos un perfil técnico con experiencia, y valoramos especialmente conocimientos en tratamiento de agua y sistemas de ósmosis inversa, con el objetivo de fortalecer y profesionalizar esta área clave dentro de la compañía.🔧 Principales responsabilidades: Desarrollo de la operación integral de sistemas purificadores de agua. Instalación, mantenimiento, reparación y traslado de equipos. Diagnóstico y resolución de fallas técnicas. Entrega de insumos a clientes, garantizando una experiencia de servicio de calidad en cada visita. Gestión y mantenimiento de la camioneta de trabajo, asegurando que cuente con el equipamiento necesario. Registro y documentación de tareas realizadas.✅ Requisitos: Formación y/o experiencia en refrigeración, electricidad o afines. Experiencia previa en tareas similares. Licencia de conducir vigente (excluyente). Disponibilidad inmediata.➕ Será un plus contar con experiencia en tratamiento de agua y ósmosis inversa.🎁 Te ofrecemos Contratación en relación de dependencia (Convenio de Comercio 130/75). Jornada laboral: Lunes a Viernes de 08 a 17 hs + esquema rotativo según demanda. Ubicación: Villa Ortúzar, CABA.🎉Beneficios: Viandas 4 días semanales. Día de cumpleaños libre.¡Si te interesa la propuesta, no dudes en postularte!', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '06-04-2026', '06-04-2026 14:59:50', '10-04-2026 09:12:24', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 22, 36, 1, NULL, 0, 0, NULL, 40, 'Destacados', 'bumeran', 'destacado', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118219978.html', '2026-04-13T07:05:55.118669');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118228052, 13085275, 'Encargada de Local Shopping- CABA', 'MODUM Consultora', 'Encargada de Local | Galerías PacíficoEn Modum Consultora estamos acompañando a TNB, empresa que representa reconocidas marcas internacionales del rubro infantil como Carter’s, OshKosh B’gosh y Skip Hop, en la búsqueda de una Encargada de Local para liderar su tienda en Galerías Pacífico.Buscamos un perfil con experiencia en ventas y liderazgo, orientación a resultados y capacidad para gestionar integralmente el funcionamiento del local, acompañando al equipo y asegurando una excelente experiencia para el cliente.¿Qué vas a hacer? Coordinar y liderar el equipo de ventas • Acompañar y desarrollar al equipo en el día a día • Brindar atención y asesoramiento al cliente • Gestionar la caja y facturación • Supervisar stock y reposición de mercadería • Asegurar el orden, la imagen y el correcto funcionamiento del local¿Qué buscamos? Experiencia en ventas (excluyente) • Experiencia previa en roles de liderazgo o supervisión • Muy buena presencia y excelente trato interpersonal • Perfil proactivo, resolutivo y con capacidad de organización • Fuerte orientación comercial y a resultados • Disponibilidad full-time • Inglés intermedio (valorado) • Conocimiento de sistema Dragonfish (no excluyente) • Experiencia en indumentaria de bebés y niños (valorada)¿Qué ofrecemos? Incorporación inmediata • Muy buen clima de trabajo • Posibilidades de desarrollo y crecimiento • Sueldo bajo convenio de comercio + comisiones por ventasModalidad de trabajo Jornada full-time • Horarios rotativos de lunes a lunesSi te sentís identificado/a con la propuesta, podés postularte o enviarnos tu CV para conocerte mejor', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '11-04-2026', '11-04-2026 08:34:56', '12-04-2026 18:57:33', '2026-04-11', NULL, NULL, '2026-04-11T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13085275_bum_vdc0f5aca.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118228052.html', '2026-04-13T07:05:55.118827');
