INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227079, NULL, 'Jefe de Garantía de Calidad Operacional', 'Confidencial', 'Jefe de Garantía de Calidad OperacionalPara Laboratorio Medicinal de Capitales NacionalesBuscamos un profesional con visión de excelencia para liderar la integridad de nuestras operaciones productivas. Tu misión será asegurar que cada etapa de fabricación, acondicionamiento y control se ejecute bajo los más altos estándares de calidad, garantizando la seguridad del paciente y el cumplimiento normativo.El Desafío: Aseguramiento Normativo: Garantizar que todas las operaciones se realicen en estricto cumplimiento con las normativas GMP. Control de Procesos: Supervisar que los procesos de fabricación y acondicionamiento sean consistentes, seguros y conformes a los estándares establecidos. Gestión Operativa: Liderar la liberación de lotes en planta, gestión de desvíos, investigaciones y capacitaciones del personal. Mejora Continua: Promover una cultura de calidad operativa basada en la transparencia y la eficiencia.Requisitos del Perfil: Nivel Académico: Profesional graduado de la carrera de Farmacia o carreras afines (excluyente). Experiencia: Mínimo de 5 años en posiciones similares dentro de la Industria Farmacéutica. Habilidades Técnicas: Conocimiento experto en estándares de calidad GMP (excluy). Idiomas: Inglés (nivel intermedio, no excluyente). Herramientas Digitales: Manejo avanzado de herramientas de computación.Competencias Clave: Buscamos un perfil con marcado liderazgo y capacidad de trabajo en equipo, que destaque por su: Iniciativa y proactividad. Capacidad analítica para la resolución de problemas complejos. Excelente comunicación y transparencia e integridad profesional. Sentido de orden, organización y compromiso con los resultados.¿Qué ofrecemos? Ingreso a un laboratorio nacional con solidas perspectivas de crecimiento Oportunidades de crecimiento y desarrollo profesional.¡Si buscas un rol donde tu capacidad técnica y humana impacte directamente en la salud, postulate! 🖊', 1, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 14:31:51', '10-04-2026 14:34:39', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 16, 84, 1, NULL, NULL, NULL, NULL, 40, 'Destacados', 'bumeran', 'destacado', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227079.html', '2026-04-13T07:05:55.119300');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223653, 2069220, 'Responsable de Calidad - Industria Pesquera | Trelew', 'WayOn', 'Buscamos un perfil con fuerte presencia en planta, capacidad de liderazgo e influencia, que pueda ser referente de calidad en un entorno productivo dinámico y exigente.🎯 Objetivo de la posición Liderar el área de Calidad, asegurando el cumplimiento de normas y estándares, con un rol activo en planta y fuerte foco en la mejora continua y la capacitación de los equipos.🧩 Principales responsabilidades Asegurar la correcta implementación y cumplimiento de normas de calidad e inocuidad (BPM, POES, HACCP) Liderar el equipo de Calidad (control, administración y limpieza) • Estar presente en planta, especialmente en momentos clave como la recepción de materia prima Diseñar e implementar capacitaciones internas, generando conciencia y buenas prácticas Elaborar y dar seguimiento a indicadores, reportes y planes de acción Coordinar auditorías internas y externas, y sostener certificaciones Trabajar de manera transversal con Producción y otras áreas Generar espacios de trabajo y alineación con el equipo y la gerencia🔍 ¿Qué buscamos? Experiencia en industria pesquera (excluyente) Sólidos conocimientos en normas de calidad e inocuidad Experiencia liderando equipos de trabajo Perfil hands-on, con fuerte presencia en planta Habilidades de comunicación, influencia y manejo de auditorio Capacidad para ordenar, estructurar y dar seguimiento con indicadores Manejo de Excel (reportes y análisis) • Inglés (deseable)Valoramos perfiles que combinen solidez técnica con capacidad de llegada al equipo, logrando que los estándares se sostengan en la operación diaria.', 0, 'Trelew, Chubut', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 14:27:30', '08-04-2026 14:28:29', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 16, 84, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2069220_bum_vbba60d45.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223653.html', '2026-04-13T07:05:55.119449');
